sp_widget.client_script:
api.controller = function($scope, spUtil, $timeout, $interval, $window, $sce) {
	var c = this;

	var DEFAULT_CREDIT_TENOR = 45;
	var MAX_UPLOAD_BYTES = 5 * 1024 * 1024;
	var SEGMENT_ORDER = ['Cement', 'RMC', 'BPD'];

	function parseOcrNumber(raw) {
		if (raw === undefined || raw === null || raw === '') return NaN;
		return parseFloat(raw.toString().replace(/,/g, '').trim());
	}

	function emptyPanTotals() {
		return { limit: 0, bg: 0, activeBg: 0, netExposure: 0, outstanding: 0 };
	}

	function emptySegmentTotals() {
		return SEGMENT_ORDER.map(function(seg) {
			return { segment: seg, sites: 0, limit: 0, activeBg: 0, netExposure: 0, outstanding: 0 };
		});
	}

	function segmentKey(segText) {
		var s = (segText || '').toString().toLowerCase();
		if (s.indexOf('cement') !== -1) return 'Cement';
		if (s.indexOf('rmc') !== -1) return 'RMC';
		if (s.indexOf('bpd') !== -1) return 'BPD';
		return null;
	}

	function getDefaultPanLevel() {
		return {companyType: 'Unlisted', netWorth: null, loansAdvances: null, panNote: '' };
	}

	c.data.currentStep       = 1;
	c.data.customers         = [];
	c.data.panNumber         = '';
	c.data.panSearchText     = '';
	c.data.panSelectedText   = '';
	c.data.panSuggestions    = [];
	c.data.panSearching      = false;
	c.data.panNoMatch        = false;
	c.data.isFetching        = false;
	c.data.selectedCustomers = [];
	c.data.panLevel          = getDefaultPanLevel();
	c.data.isSubmitting      = false;
	c.data.localSearch       = '';
	c.data.currentPage       = 1;
	c.data.itemsPerPage      = 10;
	c.data.lastProcessedDoc  = '';
	c.data.thresholds = { cement: 5000000, rmc: 2500000, bpd: 2500000, defaultSeg: 2500000, crossSegment: 15000000 };

	c.rawFile              = null;
	c.data.fileData        = null;
	c.data.fileName        = '';
	c.data.fileType        = '';
	c.data.sysId           = null;
	c.data.targetTable     = '';
	c.data.processing      = false;
	c.data.statusMsg       = '';
	c.data.result          = {};
	c.data.aiSummaryPoints = [];
	c.data.isManualMode    = false;
	c.data.externalRating  = '';
	c.data.documentType    = 'No Document';

	c.data.panTotals     = emptyPanTotals();
	c.data.segmentTotals = emptySegmentTotals();
	c.data.reviewSites   = null;
	c.data.reviewSummary = null;

	c.segPotentials = [];
	c.macl = { page: 1, size: 10, search: '', scope: 'requested' };   // scope: 'requested' | 'all'
	var maclView = { src: null, key: null, groups: [], total: 0, pages: 1, start: 0, end: 0,
									totals: { sites: 0, macl: 0, currentCl: 0, updatedCl: 0 } };

	var pollTimer  = null;
	var pollCount  = 0;
	var MAX_POLLS  = 24;

	c.formatINR = function(val) {
		if (val === undefined || val === null || val === '') return '0.00';
		var num = parseFloat(val);
		if (isNaN(num)) return '0.00';
		return num.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
	};

	c.goToDashboard = function() {
		$window.location.href = '?id=uclm_dashboard';
	};

	c.recalculatePanTotals = function() {
		var totals = emptyPanTotals();
		var segTotals = emptySegmentTotals();
		var segIndex = {};
		segTotals.forEach(function(s) { segIndex[s.segment] = s; });

		(c.data.customers || []).forEach(function(cust) {
			var limit    = parseFloat(cust.limit) || 0;
			var bg       = parseFloat(cust.bg) || 0;
			var activeBg = parseFloat(cust.activeBg) || 0;
			var os       = parseFloat(cust.outstanding) || 0;

			totals.limit       += limit;
			totals.bg          += bg;
			totals.activeBg    += activeBg;
			totals.outstanding += os;

			var key = segmentKey(cust.segmentDisplay) || segmentKey(cust.segmentValue);
			var seg = key ? segIndex[key] : null;
			if (seg) {
				seg.sites++;
				seg.limit       += limit;
				seg.activeBg    += activeBg;
				seg.outstanding += os;
			}
		});

		totals.netExposure = totals.limit - totals.activeBg;
		segTotals.forEach(function(s) { s.netExposure = s.limit - s.activeBg; });

		c.data.panTotals     = totals;
		c.data.segmentTotals = segTotals;
	};

	// Step 1
	c.handlePanInput = function() {
		var query = c.data.panSearchText ? c.data.panSearchText.toUpperCase().trim() : '';
		c.data.panNoMatch = false;

		if (c.data.panSelectedText && query === c.data.panSelectedText.toUpperCase()) return;
		c.data.panSelectedText = '';

		if (query.length === 10 && /^[A-Z0-9]+$/.test(query)) {
			c.data.panSuggestions = [];
			c.data.panSearching   = false;
			c.data.panNumber      = query;
			c.fetchCustomers();
		} else if (query.length >= 3) {
			c.data.panNumber    = '';
			c.data.customers    = [];
			c.data.panSearching = true;
			c.server.get({ action: 'fetch_pan_suggestions', panNumber: query }).then(function(r) {
				if (c.data.panSearchText && c.data.panSearchText.toUpperCase().trim() === query) {
					c.data.panSuggestions = r.data.panSuggestions || [];
					c.data.panNoMatch     = c.data.panSuggestions.length === 0;
					c.data.panSearching   = false;
				}
			}).catch(function() {
				if (c.data.panSearchText && c.data.panSearchText.toUpperCase().trim() === query) {
					c.data.panSearching = false;
				}
			});
		} else {
			c.data.panNumber      = '';
			c.data.panSuggestions = [];
			c.data.panSearching   = false;
			c.data.customers      = [];
			c.data.panTotals      = emptyPanTotals();
			c.data.segmentTotals  = emptySegmentTotals();
			c.data.ongoingReq     = null;
		}
	};

	c.selectPan = function(selectedPan, selectedName) {
		c.data.panNumber       = selectedPan;
		c.data.panSelectedText = selectedName ? (selectedPan + ' – ' + selectedName) : selectedPan;
		c.data.panSearchText   = c.data.panSelectedText;
		c.data.panSuggestions  = [];
		c.data.panSearching    = false;
		c.data.panNoMatch      = false;
		c.fetchCustomers();
	};

	c.fetchCustomers = function() {
		c.data.isFetching = true;
		var currentPan = c.data.panNumber;

		c.server.get({ action: 'fetch_customers', panNumber: currentPan }).then(function(r) {
			if (c.data.panNumber === currentPan) {
				c.data.customers  = r.data.customers;
				c.data.ongoingReq = r.data.ongoingReq;
				c.data.isFetching = false;
				c.recalculatePanTotals();

				if (c.data.customers && c.data.customers.length > 0) {
					c.data.customers.forEach(function(cust) {
						cust.isSapLoading = true;
						c.fetchSapForCust(cust, currentPan);
					});
				}
			}
		}).catch(function() {
			if (c.data.panNumber === currentPan) {
				c.data.isFetching = false;
				spUtil.addErrorMessage("Error fetching basic PAN details from ServiceNow.");
			}
		});
	};

	c.fetchSapForCust = function(cust, currentPan) {
		c.server.get({
			action: 'fetch_sap_data', custCode: cust.code, salesOrg: cust.salesOrg, bgExpiryRaw: cust.bgExpiryRaw
		}).then(function(r) {
			if (c.data.panNumber !== currentPan) return;
			var sap = r.data.sapData;

			cust.limit    = sap.limit || 0;
			cust.bg       = sap.bg || 0;
			cust.activeBg = sap.activeBg || 0;

			if (sap.bgExpiry && sap.bgExpiry !== "0000-00-00") {
				cust.bgExpiryRaw = sap.bgExpiry;
				cust.bgExpiry    = sap.bgExpiry;
			}
			if (sap.nod > 0) cust.nod = sap.nod;
			if (sap.age > 0) cust.age = sap.age;
			if (sap.outstanding > 0) cust.outstanding = sap.outstanding;

			cust.isSapLoading = false;
			c.recalculatePanTotals();
		}).catch(function() {
			if (c.data.panNumber !== currentPan) return;
			cust.limit = 0; cust.bg = 0; cust.activeBg = 0;
			cust.isSapLoading = false;
			c.recalculatePanTotals();
		});
	};

	c.isAnySapLoading = function() {
		return !!(c.data.customers && c.data.customers.some(function(cust) { return cust.isSapLoading; }));
	};

	c.hasSelection = function() {
		return !!(c.data.customers && c.data.customers.some(function(cust) { return cust.selected === true; }));
	};

	c.getSelectedSegment = function() {
		var selected = (c.data.customers || []).find(function(cst) { return cst.selected; });
		return selected ? selected.segmentDisplay : null;
	};

	c.proceedToStep = function(stepNum) {
		if (stepNum === 2 && c.data.currentStep === 1) {
			c.data.selectedCustomers = c.data.customers.filter(function(cust) { return cust.selected; });

			c.data.selectedCustomers.forEach(function(cust) {
				if (cust.creditTenor === null || cust.creditTenor === undefined || cust.creditTenor === '') {
					cust.creditTenor = DEFAULT_CREDIT_TENOR;
				}
			});

			c.recalculateAllRows();
		}
		c.data.currentStep = stepNum;
	};

	c.getFilteredCustomers = function() {
		if (!c.data.customers) return [];
		var searchStr = (c.data.localSearch || '').toLowerCase();
		return c.data.customers.filter(function(cust) {
			return cust.name.toLowerCase().includes(searchStr) ||
				cust.code.toLowerCase().includes(searchStr) ||
				(cust.city && cust.city.toLowerCase().includes(searchStr)) ||
				(cust.segmentDisplay && cust.segmentDisplay.toLowerCase().includes(searchStr));
		});
	};

	c.getPaginatedCustomers = function() {
		var filtered = c.getFilteredCustomers();
		var startIndex = (c.data.currentPage - 1) * c.data.itemsPerPage;
		return filtered.slice(startIndex, startIndex + c.data.itemsPerPage);
	};

	c.totalPages = function() {
		return Math.ceil(c.getFilteredCustomers().length / c.data.itemsPerPage) || 1;
	};

	c.selectAllInView = function(selectAll) {
		var targetSegment = c.getSelectedSegment();
		var paginated = c.getPaginatedCustomers();

		if (selectAll && !targetSegment) {
			var firstValid = paginated.find(function(cust) { return !cust.hasActiveRequest && !cust.missingTSH; });
			if (firstValid) targetSegment = firstValid.segmentDisplay;
		}

		paginated.forEach(function(cust) {
			if (!cust.hasActiveRequest && !cust.missingTSH) {
				if (selectAll) {
					if (cust.segmentDisplay === targetSegment) cust.selected = true;
				} else {
					cust.selected = false;
				}
			}
		});
	};

	// Step 2
	function isBlank(v) { return v === null || v === undefined || v === ''; }
	function num(v) { return parseFloat(v) || 0; }

	c.calcRow = function(cust) {
		if (cust.totalPotential < 0) cust.totalPotential = 0;
		if (cust.currentSob < 0) cust.currentSob = 0;
		if (cust.expectedSob < 0) cust.expectedSob = 0;
		if (cust.orderRate < 0) cust.orderRate = 0;
		if (cust.desiredLimit < 0) cust.desiredLimit = 0;
		if (cust.creditTenor < 0) cust.creditTenor = 0;

		var pot = num(cust.totalPotential);
		cust.currentSobAmt        = num(cust.currentSob);
		cust.expectedPotentialAmt = num(cust.expectedSob);
		cust.currentSobPct  = pot > 0 ? Math.round((cust.currentSobAmt / pot) * 10000) / 100 : 0;
		cust.expectedSobPct = pot > 0 ? Math.round((cust.expectedPotentialAmt / pot) * 10000) / 100 : 0;

		if (c.data.panLevel.companyType !== 'Listed') {
			var tenor = cust.creditTenor || 0;
			cust.calculatedP1 = cust.expectedPotentialAmt * (cust.orderRate || 0) * (tenor / 30);
		} else {
			cust.calculatedP1 = 0;
		}
	};

	c.sobError = function(cust, field) {
		var val = cust[field];
		if (isBlank(val)) return '';
		if (val < 0) return 'Negative not allowed';
		if (num(val) === 0) return '';
		if (isBlank(cust.totalPotential) || num(cust.totalPotential) <= 0) return 'Enter Potential first';
		if (num(val) > num(cust.totalPotential)) return 'Cannot exceed Potential (' + num(cust.totalPotential) + ')';
		return '';
	};

	c.siteNetExposure = function(cust) {
		return num(cust.desiredLimit) - num(cust.activeBg);
	};

	c.getGridTotals = function() {
		var t = { limit: 0, activeBg: 0, desired: 0, netExposure: 0 };
		(c.data.selectedCustomers || []).forEach(function(cust) {
			t.limit    += num(cust.limit);
			t.activeBg += num(cust.activeBg);
			t.desired  += num(cust.desiredLimit);
		});
		t.netExposure = t.desired - t.activeBg;
		return t;
	};

	c.getQtyUnit = function() {
		return c.getSelectedSegment() === 'RMC' ? 'CuM' : 'MT';
	};

	c.recalculateAllRows = function() {
		if (!c.data.selectedCustomers) return;
		c.data.selectedCustomers.forEach(function(cust) { c.calcRow(cust); });
	};

	// Potential / Current SOB / Expected SOB of one site for aggregation:
	// sites in this request -> values entered in Step 2; every other site -> customer master values.
	function siteValues(cust) {
		if (cust.selected) {
			return { pot: num(cust.totalPotential), cur: num(cust.currentSob), exp: num(cust.expectedSob) };
		}
		return { pot: num(cust.masterPotential), cur: num(cust.masterCurrentSob), exp: num(cust.masterExpectedSob) };
	}

	// Segment-wide aggregate (all sites of the requested segment under the PAN)
	c.getSummaryMetrics = function() {
		var key = segmentKey(c.getSelectedSegment());
		var m = { totalPot: 0, currAmt: 0, expectedPot: 0 };

		(c.data.customers || []).forEach(function(cust) {
			var k = segmentKey(cust.segmentDisplay) || segmentKey(cust.segmentValue);
			if (!key || k !== key) return;
			var v = siteValues(cust);
			m.totalPot    += v.pot;
			m.currAmt     += v.cur;
			m.expectedPot += v.exp;
		});

		return {
			currentSobPct: m.totalPot > 0 ? ((m.currAmt / m.totalPot) * 100).toFixed(2) : "0.00",
			totalPot: m.totalPot,
			expectedPotNum: m.expectedPot,
			expectedPot: Math.round(m.expectedPot).toLocaleString('en-IN'),
			currAmt: Math.round(m.currAmt).toLocaleString('en-IN')
		};
	};

	c.handleDocTypeChange = function() {
		c.rawFile = null;
		c.data.fileName = '';
		c.data.fileData = null;
		c.data.fileType = '';
		var fileEl = document.getElementById('financialReport');
		if (fileEl) fileEl.value = '';
	};

	c.isFormValid = function() {
		if (!c.data.panLevel.companyType) return false;
		if (!c.data.selectedCustomers || c.data.selectedCustomers.length === 0) return false;

		for (var i = 0; i < c.data.selectedCustomers.length; i++) {
			var cust = c.data.selectedCustomers[i];
			if (isBlank(cust.totalPotential) || cust.totalPotential < 0) return false;
			if (isBlank(cust.currentSob) || c.sobError(cust, 'currentSob')) return false;
			if (isBlank(cust.expectedSob) || c.sobError(cust, 'expectedSob')) return false;
			if (c.data.panLevel.companyType !== 'Listed' && (!cust.orderRate || cust.orderRate < 0)) return false;
			if (cust.creditTenor === undefined || cust.creditTenor === null || cust.creditTenor < 0) return false;
			if (!cust.desiredLimit || cust.desiredLimit < 0) return false;
		}
		if (!c.data.documentType) return false;
		if (c.data.documentType !== 'No Document' && !c.rawFile && c.data.lastProcessedDoc !== (c.data.documentType + c.data.fileName)) return false;
		return true;
	};

	c.handleFileUpload = function(element) {
		var file = element.files[0];
		if (!file) return;

		if (file.size > MAX_UPLOAD_BYTES) {
			spUtil.addErrorMessage("File size exceeds the 5MB limit. Please compress or upload a smaller document.");
			c.handleDocTypeChange();
			return;
		}

		$timeout(function() {
			c.rawFile = file;
			c.data.fileName = file.name;
			c.data.fileType = file.type;
		});

		var reader = new FileReader();
		reader.onload = function(e) {
			$timeout(function() { c.data.fileData = e.target.result.split(',')[1]; });
		};
		reader.readAsDataURL(file);
	};

	// Step 3
	c.generateAiDraft = function() {
		c.data.isSubmitting = true;
		var currentDocKey = c.data.documentType === 'No Document' ? 'No Document' : c.data.documentType + c.data.fileName;

		if ((c.data.lastProcessedDoc === currentDocKey && Object.keys(c.data.result || {}).length > 0) ||
				(c.data.isManualMode && currentDocKey == 'No Document')) {
			c.autoMapMatrix();
			c.data.currentStep = 3;
			c.data.isSubmitting = false;
			return;
		}

		if (c.data.documentType === 'No Document') {
			c.data.action = 'fetch_parameters';
			c.server.update().then(function() {
				c.data.action        = '';
				c.data.currentStep   = 3;
				c.data.processing    = false;
				c.data.isManualMode  = true;
				c.data.error         = 'Manual Entry Mode: No Document uploaded. Parameters you do not set use their lowest score — review and adjust where needed.';
				c.data.result        = {};
				c.autoMapMatrix();
				c.data.lastProcessedDoc = 'No Document';
				c.data.isSubmitting = false;
			}).catch(function() {
				c.data.isSubmitting = false;
				spUtil.addErrorMessage("Failed to load Manual Entry parameters.");
			});
			return;
		}

		c.data.action      = 'create_record';
		c.data.currentStep = 3;
		c.data.processing  = true;
		c.data.statusMsg   = 'Uploading attachment and linking securely...';

		c.server.update().then(function() {
			c.data.action = '';
			if (c.data.serverError) {
				spUtil.addErrorMessage(c.data.serverError);
				c.data.isSubmitting = false;
				c.data.currentStep  = 2;
				c.data.processing   = false;
				return;
			}
			c.data.isSubmitting = false;
			c.data.statusMsg    = 'Invoking OCR engine scanning models...';
			c.startPolling();
		}).catch(function() {
			spUtil.addErrorMessage("Server configuration error.");
			c.data.isSubmitting = false;
			c.data.currentStep  = 2;
			c.data.processing   = false;
		});
	};

	var stopPolling = function() {
		if (angular.isDefined(pollTimer)) {
			$interval.cancel(pollTimer);
			pollTimer = undefined;
		}
	};

	c.startPolling = function() {
		pollCount = 0;
		stopPolling();

		pollTimer = $interval(function() {
			pollCount++;
			c.data.action = 'poll';
			c.server.update().then(function() {
				c.data.action = '';
				var isDone = (c.data.ocrStatus === 'failed' || c.data.ocrStatus === 'success' || pollCount >= MAX_POLLS);

				if (isDone) {
					stopPolling();
					$timeout(function() {
						c.data.processing = false;
						c.data.statusMsg = '';

						if (c.data.ocrStatus === 'success') {
							c.data.isManualMode = false;
							if (c.data.panLevel.companyType === 'Listed') {
								if (c.data.result.net_worth) {
									var nw = parseOcrNumber(c.data.result.net_worth);
									if (!isNaN(nw)) c.data.panLevel.netWorth = nw;
								}
								if (c.data.result.loans_advances) {
									var la = parseOcrNumber(c.data.result.loans_advances);
									if (!isNaN(la)) c.data.panLevel.loansAdvances = la;
								}
							}
						} else {
							c.data.error = 'System Notice: OCR Processing timeout or failure. Form has been unlocked for manual parameter entry.';
							c.data.result = {};
							c.data.isManualMode = true;
						}
						c.data.lastProcessedDoc = c.data.documentType + c.data.fileName;
						c.autoMapMatrix();
					});
				} else if (c.data.processing) {
					c.data.statusMsg = 'Extracting fields (' + (pollCount * 10) + 's elapsed)...';
				}
			});
		}, 10000);
	};

	// Segment-wise total potential for Step 3 (kept off c.data; refreshed when Step 3 opens).
	// Sites in the request: Step 2 value. Other sites: customer master value. Empty segments are hidden.
	c.refreshSegmentPotentials = function() {
		var rows = SEGMENT_ORDER.map(function(seg) {
			return { segment: seg, unit: seg === 'RMC' ? 'CuM' : 'MT', sites: 0, inRequest: 0, potential: 0 };
		});
		var index = {};
		rows.forEach(function(r) { index[r.segment] = r; });

		(c.data.customers || []).forEach(function(cust) {
			var row = index[segmentKey(cust.segmentDisplay) || segmentKey(cust.segmentValue)];
			if (!row) return;
			row.sites++;
			if (cust.selected) row.inRequest++;
			row.potential += siteValues(cust).exp;
		});

		c.segPotentials = rows.filter(function(r) { return r.sites > 0; });
	};

	// Matrix auto-mapping (instant feedback only; the authoritative calc runs server-side)
	c.applyMap = function(paramObj, matchSysId, rawValueStr, mappingType) {
		if (rawValueStr !== undefined && rawValueStr !== null && rawValueStr !== '') {
			paramObj.extractedValue = rawValueStr;
		}
		// Input-mapped values are re-evaluated when Step 2 numbers change (unless the user overrode them)
		var refreshInput = mappingType === 'Input' && paramObj.autoMapped && paramObj.mappingType === 'Input' && !paramObj.isChanged;
		if (matchSysId && (!paramObj.selectedValue || paramObj.isDefaulted || refreshInput)) {
			paramObj.isDefaulted   = false;
			paramObj.selectedValue = matchSysId;
			paramObj.autoMapped    = true;
			paramObj.mappingType   = mappingType || 'AI';
			paramObj.originalValue = matchSysId;
			var matchedOpt = paramObj.options.find(function(o) { return o.sys_id === matchSysId; });
			paramObj.originalLabel = matchedOpt ? matchedOpt.label : 'Unknown';
			paramObj.isChanged     = false;
		}
	};

	c.retriggerNetWorthMap = function() {
		c.autoMapMatrix();
	};

	c.isParamRelevant = function(pName, param) {
		var tag = param && param.segmentTag;
		var seg = c.getSelectedSegment();

		if (tag) return tag === 'All' || tag === seg;

		var name = pName.toLowerCase();
		var isCem = name.indexOf('cement') !== -1;
		var isRmc = name.indexOf('rmc') !== -1;
		var isBpd = name.indexOf('bpd') !== -1;
		if (!isCem && !isRmc && !isBpd) return true;
		if (isCem && seg === 'Cement') return true;
		if (isRmc && seg === 'RMC') return true;
		if (isBpd && seg === 'BPD') return true;
		return false;
	};

	c.evaluateNumberCondition = function(optionsArray, valueToCheck) {
		var val = parseFloat(valueToCheck);
		if (isNaN(val)) return '';

		var defaultOptionId = '';

		for (var i = 0; i < optionsArray.length; i++) {
			var opt = optionsArray[i];

			if (opt.operator) {
				if (opt.operator === 'gte' && val >= opt.minValue) return opt.sys_id;
				if (opt.operator === 'lte' && val <= opt.maxValue) return opt.sys_id;
				if (opt.operator === 'gt'  && val >  opt.minValue) return opt.sys_id;
				if (opt.operator === 'lt'  && val <  opt.maxValue) return opt.sys_id;
				if (opt.operator === 'between' && val >= opt.minValue && val <= opt.maxValue) return opt.sys_id;
				continue;
			}

			var cleanLabel = opt.label.toLowerCase().split('(score')[0].replace(/,/g, '').trim();

			if (/\bdefault\b/.test(cleanLabel) && !defaultOptionId) {
				defaultOptionId = opt.sys_id;
				continue;
			}

			var rangeMatch = cleanLabel.match(/([\d.]+)\s*-\s*([\d.]+)/);
			if (rangeMatch) {
				var min = parseFloat(rangeMatch[1]), max = parseFloat(rangeMatch[2]);
				if (val >= min && val <= max) return opt.sys_id;
				continue;
			}

			var singleMatch = cleanLabel.match(/([\d.]+)/);
			if (singleMatch) {
				var numVal = parseFloat(singleMatch[1]);
				if (cleanLabel.indexOf('>=') !== -1 && val >= numVal) return opt.sys_id;
				else if (cleanLabel.indexOf('<=') !== -1 && val <= numVal) return opt.sys_id;
				else if (cleanLabel.indexOf('=') === -1 && (cleanLabel.indexOf('>') !== -1 || cleanLabel.indexOf('above') !== -1) && val > numVal) return opt.sys_id;
				else if (cleanLabel.indexOf('=') === -1 && (cleanLabel.indexOf('<') !== -1 || cleanLabel.indexOf('below') !== -1) && val < numVal) return opt.sys_id;
				else if (val === numVal) return opt.sys_id;
			}
		}

		return defaultOptionId;
	};

	c.autoMapMatrix = function() {
		var companyAge = 0;
		(c.data.customers || []).forEach(function(cust) {
			var siteAge = parseFloat(cust.age) || 0;
			if (siteAge > companyAge) {
				companyAge = siteAge;
			}
		});

		var metrics = c.getSummaryMetrics();
		var netWorth = parseFloat(c.data.panLevel.netWorth) || 0;
		var isAiActive = (!c.data.isManualMode && c.data.documentType !== 'No Document');

		angular.forEach(c.data.groupedParameters, function(paramsArray) {
			paramsArray.forEach(function(p) {
				var pName = p.name.toLowerCase();
				if (isAiActive) applyAiMappings(p, pName);
				applyInputMappings(p, pName, metrics, companyAge, netWorth);
			});
		});

		c.applyLowestDefaults();
		c.refreshSegmentPotentials();
	};

	// Optional parameters: lowest-score default
	c.getLowestOption = function(param) {
		var best = null;
		(param && param.options || []).forEach(function(o) {
			if (!best || (parseFloat(o.score) || 0) < (parseFloat(best.score) || 0)) best = o;
		});
		return best;
	};

	c.applyLowestDefaults = function() {
		angular.forEach(c.data.groupedParameters, function(paramsArray) {
			paramsArray.forEach(function(p) {
				if (!c.isParamRelevant(p.name, p) || p.selectedValue) return;
				var low = c.getLowestOption(p);
				if (!low) return;
				p.selectedValue = low.sys_id;
				p.isDefaulted   = true;
				p.autoMapped    = false;
				p.isChanged     = false;
				p.changeLog     = '';
			});
		});
	};

	c.getDefaultedCount = function() {
		var n = 0;
		angular.forEach(c.data.groupedParameters, function(arr) {
			arr.forEach(function(p) {
				if (c.isParamRelevant(p.name, p) && (p.isDefaulted || !p.selectedValue)) n++;
			});
		});
		return n;
	};

	// Display groups (first keyword match wins, groups are checked top to bottom).
	// There is no Financial Strength group: Debt Equity, Int. Coverage and the other balance-sheet
	// ratios sit under Financial Performance. Business Profile uses 'age of' / 'company age'
	// (a bare 'age' also matched "Int. Coverage").
	var PARAM_GROUPS = [
		{ key: 'wcc',        label: 'Working Capital Cycle',
		 words: ['wcc', 'working capital', 'a/r', 'ar days', 'receivable', 'debtor', 'inventory', 'a/p', 'ap days', 'payable', 'creditor'] },
		{ key: 'perf',       label: 'Financial Performance',
		 words: ['debt equity', 'debt-equity', 'debt to equity', 'd/e', 'int. coverage', 'interest coverage', 'coverage', 'interest', 'icr',
						 'debt', 'gearing', 'leverage', 'current ratio', 'quick ratio', 'liquidity', 'net worth', 'networth', 'loan',
						 'sales growth', 'growth', 'cagr', 'revenue', 'turnover', 'gross profit', 'ebitda', 'net profit', 'pat', 'margin', 'roce', 'roe'] },
		{ key: 'credit',     label: 'Credit & Compliance',
		 words: ['rating', 'risk index', 'court', 'legal', 'litigation', 'default', 'cibil', 'crif', 'dishonour', 'bounce', 'payment track'] },
		{ key: 'business',   label: 'Business Profile',
		 words: ['age of', 'company age', 'vintage', 'sales', 'potential', 'share', 'sob', 'corporate', 'mgmt', 'management', 'competence', 'business', 'market', 'client', 'order'] }
	];
	var OTHER_GROUP = { key: 'other', label: 'Other Parameters' };
	var GROUP_ORDER = ['business', 'perf', 'wcc', 'credit', 'other'];

	function paramGroupKey(name) {
		var n = (name || '').toLowerCase();
		for (var i = 0; i < PARAM_GROUPS.length; i++) {
			for (var j = 0; j < PARAM_GROUPS[i].words.length; j++) {
				if (n.indexOf(PARAM_GROUPS[i].words[j]) !== -1) return PARAM_GROUPS[i].key;
			}
		}
		return OTHER_GROUP.key;
	}

	var groupCache = { src: null, groups: [] };
	c.getParamGroups = function() {
		if (groupCache.src === c.data.groupedParameters) return groupCache.groups;
		var byKey = {};
		PARAM_GROUPS.concat([OTHER_GROUP]).forEach(function(g) { byKey[g.key] = { key: g.key, label: g.label, params: [] }; });
		angular.forEach(c.data.groupedParameters, function(arr) {
			arr.forEach(function(p) { byKey[paramGroupKey(p.name)].params.push(p); });
		});
		groupCache.src = c.data.groupedParameters;
		groupCache.groups = GROUP_ORDER.map(function(k) { return byKey[k]; }).filter(function(g) { return g.params.length > 0; });
		return groupCache.groups;
	};

	function paramWeight(p) {
		var w = 0;
		(p.options || []).forEach(function(o) { w = Math.max(w, parseFloat(o.weight) || 0); });
		return w;
	}

	// Group share of total weight, whole %, largest-remainder rounding so groups add to 100
	c.getGroupStats = function(grp) {
		var groups = c.getParamGroups();
		var rows = groups.map(function(g) {
			var relevant = 0, w = 0;
			g.params.forEach(function(p) {
				if (c.isParamRelevant(p.name, p)) { relevant++; w += paramWeight(p); }
			});
			return { g: g, relevant: relevant, w: w };
		});
		var tw = rows.reduce(function(t, r) { return t + r.w; }, 0);
		if (tw > 0) {
			rows.forEach(function(r) { var exact = r.w / tw * 100; r.pct = Math.floor(exact); r.rem = exact - r.pct; });
			var left = 100 - rows.reduce(function(t, r) { return t + r.pct; }, 0);
			rows.slice().sort(function(x, y) { return y.rem - x.rem; }).slice(0, left).forEach(function(r) { r.pct++; });
		}
		var mine = rows.filter(function(r) { return r.g === grp; })[0] || { relevant: 0, pct: 0 };
		return { relevant: mine.relevant, weightPct: tw > 0 ? mine.pct : null };
	};

	function applyAiMappings(p, pName) {
		var courtCases     = c.data.result.court_cases || '';
		var externalRating = c.data.result.rating || '';
		var riskIndex      = c.data.result.risk_index || '';

		if (pName.indexOf('rating') !== -1 && (externalRating || riskIndex)) {
			var combinedStr = (externalRating + ' ' + riskIndex).toLowerCase();
			var rOpt;
			if (combinedStr.match(/4\/5|5\/5|low/)) rOpt = p.options.find(function(o) { return o.label.indexOf('AAA') > -1; });
			else if (combinedStr.match(/3\/5|medium/)) rOpt = p.options.find(function(o) { return o.label.indexOf('BBB') > -1; });
			else if (combinedStr.match(/2\/5|unrated/)) rOpt = p.options.find(function(o) { return o.label.indexOf('BB ') > -1 || o.label.indexOf('BB (') > -1; });
			else if (combinedStr.match(/1\/5|prop/)) rOpt = p.options.find(function(o) { return o.label.indexOf('B ') > -1 || o.label.indexOf('B (') > -1; });
			if (rOpt) c.applyMap(p, rOpt.sys_id, externalRating + (riskIndex ? ' (' + riskIndex + ')' : ''), 'AI');
			return;
		}

		if (pName.indexOf('court') !== -1 || pName.indexOf('legal') !== -1) {
			var courtStr = (courtCases || '').toLowerCase();
			if (courtStr.match(/no|none|0/)) {
				var cOpt = p.options.find(function(o) { return o.label.toLowerCase().match(/no|none/); });
				if (cOpt) c.applyMap(p, cOpt.sys_id, courtCases || 'No Cases found', 'AI');
			}
			return;
		}

		var isBalanceSheet = (c.data.documentType === 'Balance Sheet');
		var revenueSuffix  = isBalanceSheet ? 'Cr' : '';

		var NUMERIC_FIELD_MAP = [
			[['ap days', 'a/p', 'payable'], 'ap_days', ' Days'],
			[['ar days', 'a/r', 'receivable'], 'ar_days', ' Days'],
			[['debt equity', 'd/e'], 'debt_equity', ' Ratio'],
			[['ebitda'], 'ebitda', ' %'],
			[['gross profit'], 'gross_profit', ' %'],
			[['interest coverage', 'icr', 'int'], 'int_coverage', ' Ratio'],
			[['inventory days'], 'inventory_days', ' Days'],
			[['wcc', 'working capital cycle'], 'net_wcc_days', ' Days'],
			[['sales growth', 'growth'], 'sales_growth', ' %'],
			[['roce'], 'roce', ' %'],
			[['roe'], 'roe', ' %'],
			[['current ratio'], 'current_ratio', ' Ratio'],
			[['revenue', 'turnover', 'sales'], 'net_revenue', revenueSuffix]
		];

		for (var i = 0; i < NUMERIC_FIELD_MAP.length; i++) {
			var keywords  = NUMERIC_FIELD_MAP[i][0];
			var resultKey = NUMERIC_FIELD_MAP[i][1];
			var suffix    = NUMERIC_FIELD_MAP[i][2];

			if (keywords.some(function(kw) { return pName.indexOf(kw) !== -1; })) {
				var raw = c.data.result[resultKey];
				if (raw !== undefined && raw !== null && raw !== '') {
					var parsed = parseOcrNumber(raw);
					if (!isNaN(parsed)) {
						var matchVal = parsed;
						var displayVal = '';

						if (suffix === 'Cr') {
							matchVal = parsed / 10000000;
							displayVal = '₹' + c.formatINR(parsed) + ' (' + matchVal.toFixed(2) + ' Cr)';
						} else if (resultKey === 'net_revenue') {
							displayVal = '₹' + c.formatINR(parsed);
						} else {
							displayVal = parsed + suffix;
						}

						c.applyMap(p, c.evaluateNumberCondition(p.options, matchVal), displayVal, 'AI');
					}
				}
				break;
			}
		}
	}

	// Current SOB % and Potential are scored on the segment-wide totals (request sites + master sites)
	function applyInputMappings(p, pName, metrics, companyAge, netWorth) {
		if (pName.indexOf('share') !== -1 || pName.indexOf('sob') !== -1) {
			c.applyMap(p, c.evaluateNumberCondition(p.options, parseFloat(metrics.currentSobPct)), metrics.currentSobPct + ' %', 'Input');
		} else if (pName.match(/\bage\b/) || pName.indexOf('vintage') !== -1) {
			c.applyMap(p, c.evaluateNumberCondition(p.options, companyAge), companyAge + ' Years', 'Input');
		} else if (pName.indexOf('potential') !== -1) {
			c.applyMap(p, c.evaluateNumberCondition(p.options, metrics.expectedPotNum), c.formatINR(metrics.expectedPotNum) + ' ' + (c.getSelectedSegment() === 'RMC' ? 'CuM' : 'MT'), 'Input');
		} else if (pName.indexOf('net worth') !== -1 && c.data.panLevel.companyType === 'Listed') {
			c.applyMap(p, c.evaluateNumberCondition(p.options, netWorth), '₹ ' + netWorth, 'Input');
		}
	}

	c.trackChange = function(param) {
		param.isDefaulted = false;
		if (!param.autoMapped) return;
		if (param.selectedValue !== param.originalValue) {
			param.isChanged = true;
			var newOpt = param.options.find(function(o) { return o.sys_id == param.selectedValue; });
			param.changeLog = '• ' + param.name + ': Override tracked from [' + param.originalLabel + '] to [' + (newOpt ? newOpt.label : 'None Selected') + ']';
		} else {
			param.isChanged = false;
			param.changeLog = '';
		}
	};

	c.getTotalRelevantParams = function() {
		var total = 0;
		angular.forEach(c.data.groupedParameters, function(arr) {
			arr.forEach(function(p) { if (c.isParamRelevant(p.name, p)) total++; });
		});
		return total;
	};

	c.getCompletedRelevantCount = function() {
		var count = 0;
		angular.forEach(c.data.groupedParameters, function(arr) {
			arr.forEach(function(p) { if (c.isParamRelevant(p.name, p) && p.selectedValue) count++; });
		});
		return count;
	};

	// Step 4
	c.prepareReviewData = function() {
		c.resetMaclPaging();
		c.applyLowestDefaults();
		c.data.externalRating = (c.data.result && c.data.result.rating) || '';
		c.data.isSubmitting  = true;
		c.data.reviewSites   = null;
		c.data.reviewSummary = null;
		c.data.serverError   = '';
		c.data.currentStep   = 4;
		c.data.action        = 'preview_review';

		c.server.update().then(function() {
			c.data.action = '';
			c.data.isSubmitting = false;
			if (c.data.serverError) {
				spUtil.addErrorMessage(c.data.serverError);
				c.data.currentStep = 3;
			}
		}).catch(function() {
			c.data.isSubmitting = false;
			c.data.currentStep = 3;
			spUtil.addErrorMessage("Failed to compute review summary.");
		});
	};

	c.pct = function(v, dp) {
		var n = parseFloat(v);
		if (isNaN(n)) return '0';
		return n.toFixed(dp === undefined ? 2 : dp);
	};

	// Step 4 composite index (P2): the PAN-wide parameters once, the segment parameters (Current SOB %,
	// Potential) of every segment that has sites, then the PAN index = segment indices weighted by MPQ x average rate.
	// Cached on reviewComposite ($$ keys are dropped when c.data is posted back).
	c.getCompositeBreakdown = function() {
		var rc = c.data.reviewComposite;
		if (!rc || !rc.segments || !rc.segments.length) return null;
		if (rc.$$bd) return rc.$$bd;

		function sumPts(rows) { return rows.reduce(function(t, r) { return t + r.pts; }, 0); }
		function sumW(rows)   { return rows.reduce(function(t, r) { return t + r.wPct; }, 0); }

		var segRows = [];
		var segs = rc.segments.map(function(seg) {
			var trace = seg.paramTrace || [];
			var tw = trace.reduce(function(t, r) { return t + (parseFloat(r.weight) || 0); }, 0);
			var rows = trace.map(function(t) {
				var wPct = tw > 0 ? (t.weight / tw) * 100 : 0;
				return {
					name: t.name, label: t.label, score: t.score, kind: t.kind, value: t.value, panWide: t.panWide,
					wPct: wPct, pts: (t.score * wPct) / 10,
					isDefault: (t.source || '').indexOf('lowest score') !== -1
				};
			});
			var common = rows.filter(function(r) { return r.panWide; });
			var own = rows.filter(function(r) { return !r.panWide; });
			var unit = seg.segment === 'RMC' ? 'CuM' : 'MT';
			own.forEach(function(r, i) {
				r.segment = seg.segment; r.unit = unit; r.first = (i === 0); r.span = own.length;
				segRows.push(r);
			});
			return {
				segment: seg.segment, unit: unit, sites: seg.siteCount,
				index: seg.index * 100, commonPts: sumPts(common), segPts: sumPts(own),
				mpq: seg.expectedPotentialSum, avgRate: seg.avgRate || 0, weight: seg.weight || 0,
				commonRows: common
			};
		});

		// PAN-wide parameters are the same for every segment: show them once (first segment's scoring)
		var byKey = {};
		segs[0].commonRows.forEach(function(r) {
			var k = paramGroupKey(r.name);
			(byKey[k] = byKey[k] || []).push(r);
		});
		var labels = {};
		PARAM_GROUPS.concat([OTHER_GROUP]).forEach(function(g) { labels[g.key] = g.label; });
		var commonGroups = GROUP_ORDER.filter(function(k) { return byKey[k]; }).map(function(k) {
			return { label: labels[k], rows: byKey[k], wPct: sumW(byKey[k]) };
		});

		// Weight share and contribution (equal shares when no segment has a weight = simple average)
		var tw = segs.reduce(function(t, sg) { return t + sg.weight; }, 0);
		segs.forEach(function(sg) {
			sg.share = tw > 0 ? (sg.weight / tw) * 100 : 100 / segs.length;
			sg.contrib = sg.index * sg.share / 100;
		});

		// Only segments that actually have customer sites are shown (empty segments are hidden)
		rc.$$bd = {
			common: { groups: commonGroups, wPct: sumW(segs[0].commonRows), pts: sumPts(segs[0].commonRows) },
			segRows: segRows,
			segments: segs,
			usedSegments: segs,
			totalWeight: tw,
			totalContrib: segs.reduce(function(t, sg) { return t + sg.contrib; }, 0),
			panIndex: rc.panIndex * 100,
			usedFallback: !!rc.usedFallback
		};
		return rc.$$bd;
	};

	// Step 4 MACL table: sites grouped by segment (Cement, RMC, BPD, then any other), with subtotals.
	// Cached on reviewMacl ($$ keys are dropped when c.data is posted back).
	c.getMaclGroups = function() {
		var rm = c.data.reviewMacl;
		if (!rm || !rm.rows) return [];
		if (rm.$$groups) return rm.$$groups;
		var byKey = {}, order = SEGMENT_ORDER.slice();
		rm.rows.forEach(function(r) {
			var k = r.segKey || r.segment || 'Other';
			if (!byKey[k]) {
				byKey[k] = { segment: k, unit: k === 'RMC' ? 'CuM' : 'MT', rows: [], inRequest: 0, macl: 0, currentCl: 0, updatedCl: 0 };
				if (order.indexOf(k) === -1) order.push(k);
			}
			var g = byKey[k];
			g.rows.push(r);
			if (r.inRequest) g.inRequest++;
			g.macl      += num(r.macl);
			g.currentCl += num(r.currentCl);
			g.updatedCl += num(r.updatedCl);
		});
		rm.$$groups = order.filter(function(k) { return byKey[k]; }).map(function(k) { return byKey[k]; });
		return rm.$$groups;
	};

	// Site counts for the Requested / All toggle (cached on the grouped rows)
	c.getMaclCounts = function() {
		var all = c.getMaclGroups();
		if (all.$$counts) return all.$$counts;
		var n = 0, req = 0;
		all.forEach(function(g) { n += g.rows.length; req += g.inRequest; });
		all.$$counts = { all: n, requested: req };
		return all.$$counts;
	};

	c.setMaclScope = function(scope) {
		c.macl.scope = scope;
		c.macl.page = 1;
	};

	// One page of MACL rows, regrouped by segment, for the chosen scope (requested sites or all sites).
	// Segment header figures and the footer total come from every site of that scope (not just the page
	// or the search hits). Cached: ng-repeat needs stable objects.
	c.getMaclPage = function() {
		var all = c.getMaclGroups();
		var scope = c.macl.scope === 'all' ? 'all' : 'requested';
		var q = (c.macl.search || '').toLowerCase().trim();
		var size = parseInt(c.macl.size, 10) || 10;
		var key = [c.macl.page, size, q, scope].join('|');
		if (maclView.src === all && maclView.key === key) return maclView;

		// Groups limited to the scope, with their own subtotals
		var totals = { sites: 0, macl: 0, currentCl: 0, updatedCl: 0 };
		var scoped = [];
		all.forEach(function(g) {
			var rows = scope === 'all' ? g.rows : g.rows.filter(function(r) { return r.inRequest; });
			if (!rows.length) return;
			var sg = { segment: g.segment, unit: g.unit, rows: rows, inRequest: 0, macl: 0, currentCl: 0, updatedCl: 0 };
			rows.forEach(function(r) {
				if (r.inRequest) sg.inRequest++;
				sg.macl      += num(r.macl);
				sg.currentCl += num(r.currentCl);
				sg.updatedCl += num(r.updatedCl);
			});
			totals.sites += rows.length; totals.macl += sg.macl;
			totals.currentCl += sg.currentCl; totals.updatedCl += sg.updatedCl;
			scoped.push(sg);
		});

		var flat = [];
		scoped.forEach(function(g) {
			g.rows.forEach(function(r) {
				if (!q || (r.name || '').toLowerCase().indexOf(q) !== -1 || (r.code || '').toLowerCase().indexOf(q) !== -1) {
					flat.push({ g: g, r: r });
				}
			});
		});

		var pages = Math.max(1, Math.ceil(flat.length / size));
		if (c.macl.page > pages) c.macl.page = pages;
		if (c.macl.page < 1) c.macl.page = 1;

		var startIdx = (c.macl.page - 1) * size;
		var groups = [];
		flat.slice(startIdx, startIdx + size).forEach(function(item) {
			var last = groups[groups.length - 1];
			if (!last || last.full !== item.g) {
				last = { segment: item.g.segment, unit: item.g.unit, full: item.g, rows: [] };
				groups.push(last);
			}
			last.rows.push(item.r);
		});

		maclView.src    = all;
		maclView.key    = [c.macl.page, size, q, scope].join('|');
		maclView.groups = groups;
		maclView.totals = totals;
		maclView.total  = flat.length;
		maclView.pages  = pages;
		maclView.start  = flat.length ? startIdx + 1 : 0;
		maclView.end    = Math.min(startIdx + size, flat.length);
		return maclView;
	};

	c.maclGo = function(p) {
		var pages = c.getMaclPage().pages;
		c.macl.page = Math.min(Math.max(1, p), pages);
	};

	c.resetMaclPaging = function() {
		c.macl.page = 1; c.macl.size = 10; c.macl.search = ''; c.macl.scope = 'requested';
		maclView.key = null;
	};

	// "55.00%" for Current SOB %, "1,000.00 MT" for Potential
	c.segParamValue = function(r) {
		if (r.value === null || r.value === undefined) return '—';
		if (r.kind === 'sob') return c.pct(r.value) + '%';
		if (r.kind === 'potential') return c.formatINR(r.value) + ' ' + r.unit;
		return r.value;
	};

	c.CREDIT_GROUPS = [
		{ key: 'safe', label: '0 – 60 Days' },
		{ key: 'warn', label: '61 – 90 Days' },
		{ key: 'risk', label: 'Above 90 Days' }
	];
	c.bucketsIn = function(groupKey) {
		var credit = c.data.reviewCredit;
		return credit ? credit.buckets.filter(function(b) { return b.group === groupKey; }) : [];
	};

	// Submit
	c.submitFinalRequest = function() {
		c.data.isSubmitting = true;
		c.data.serverError = '';
		var selectedMatrixParams = [];
		var auditLogsArray = [];
		c.applyLowestDefaults();
		var totalParamsRequired = c.getTotalRelevantParams();

		angular.forEach(c.data.groupedParameters, function(paramsArray) {
			paramsArray.forEach(function(p) {
				if (c.isParamRelevant(p.name, p) && p.selectedValue) {
					selectedMatrixParams.push({ sys_id: p.selectedValue, name: p.name, segmentTag: p.segmentTag || '' });
				}
				if (p.isChanged && p.changeLog) auditLogsArray.push(p.changeLog);
				if (c.isParamRelevant(p.name, p) && p.isDefaulted) {
					var low = c.getLowestOption(p);
					auditLogsArray.push('• ' + p.name + ': No selection — lowest score applied [' + (low ? low.label : '') + ']');
				}
			});
		});

		if (c.data.panLevel.companyType == 'Listed' && (!c.data.panLevel.netWorth || !c.data.panLevel.loansAdvances)) {
			spUtil.addErrorMessage('Validation Failed: Listed Entity overrides (Net Worth and Loans & Advances) are required.');
			c.data.isSubmitting = false;
			return;
		}
		if (selectedMatrixParams.length < totalParamsRequired) {
			spUtil.addErrorMessage('Validation Failed: You must complete all ' + totalParamsRequired + ' parameters.');
			c.data.isSubmitting = false;
			return;
		}

		c.data.externalRating       = c.data.result.rating || '';
		c.data.selectedMatrixParams = selectedMatrixParams;
		c.data.auditLogsPayload     = auditLogsArray.join('\n');
		c.data.action = 'submit_credit_request';

		c.server.update().then(function() {
			if (c.data.serverError) {
				c.data.isSubmitting = false;
				spUtil.addErrorMessage(c.data.serverError);
			} else {
				c.data.isSubmitting = false;
				c.data.action = '';
				c.data.currentStep = 5;
			}
		}).catch(function() {
			c.data.isSubmitting = false;
			spUtil.addErrorMessage("System experienced an error communicating with the backend. Please try again.");
		});
	};

	c.resetForm = function() {
		stopPolling();
		c.data.panDisplayName = '';
		c.data.currentStep       = 1;
		c.data.panNumber         = '';
		c.data.panSearchText   = '';
		c.data.panSelectedText = '';
		c.data.panSuggestions    = [];
		c.data.panSearching      = false;
		c.data.panNoMatch        = false;
		c.data.customers         = [];
		c.data.selectedCustomers = [];
		c.data.panLevel          = getDefaultPanLevel();
		c.rawFile                = null;
		c.data.fileData          = null;
		c.data.fileName          = '';
		c.data.documentType      = 'No Document';
		c.data.result            = {};
		c.data.aiSummaryPoints   = [];
		c.data.externalRating    = '';
		c.data.isManualMode      = false;
		c.data.error             = '';
		c.data.panTotals         = emptyPanTotals();
		c.data.segmentTotals     = emptySegmentTotals();
		c.data.lastProcessedDoc  = '';
		c.data.reviewSites       = null;
		c.data.reviewSummary     = null;
		c.segPotentials          = [];
		c.resetMaclPaging();
	};

	$scope.$on('$destroy', function() {
		stopPolling();
	});
};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Oxygen:wght@300;400;700&display=swap');

/* Page + abg rising-sun header banner */
.clm-widget, .clm-widget *, .clm-widget *::before, .clm-widget *::after { box-sizing:border-box; }
.clm-nt-page { background:white; padding:24px 32px; border-radius:8px; color:#1a1a1a; }

.clm-hero {
  position:relative; isolation:isolate; overflow:hidden;
  display:flex; align-items:center; justify-content:space-between; gap:16px 24px;
  min-height:200px; padding:26px 32px; border-radius:12px;
  background:#7A1012; color:#fff; box-shadow:0 10px 28px rgba(122,16,18,.25);
}
/* sun rays fanning from a half-sun at ~72% on the bottom edge */
.clm-hero::before {
  content:""; position:absolute; inset:0; z-index:-3;
  background:
    repeating-conic-gradient(from -90deg at 72% 100%,
      #F3CE52 0deg 5deg, #F9A04A 5deg 9deg, #F3712A 9deg 14deg,
      #9E1715 14deg 18deg, #DA1D26 18deg 23deg, #7A1012 23deg 26deg);
}
/* solid maroon text zone fading into the rays */
.clm-hero::after {
  content:""; position:absolute; inset:0; z-index:-2;
  background:linear-gradient(90deg, #7A1012 0%, #9E1715 46%, rgba(158,23,21,.82) 56%, rgba(158,23,21,.25) 70%, rgba(122,16,18,0) 82%);
}
/* segmented half-sun */
.clm-hero-sun {
  position:absolute; left:72%; bottom:-64px; z-index:-1; width:128px; height:128px; border-radius:50%;
  transform:translateX(-50%);
  background:
    repeating-linear-gradient(0deg, transparent 0 11px, rgba(122,16,18,.85) 11px 14px),
    radial-gradient(circle, #F3CE52 0 55%, #F9A04A 100%);
  box-shadow:0 0 0 6px rgba(243,206,82,.25);
}
.clm-hero-text { position:relative; max-width:640px; }
.clm-hero-bar { width:44px; height:6px; border-radius:3px; margin-bottom:12px; background:linear-gradient(90deg,#F3CE52,#F3712A); }
.clm-hero-title { margin:0 0 6px; font-size:26px; font-weight:700; line-height:1.25; color:#fff; }
.clm-hero-accent { color:#F3CE52; }
.clm-hero-sub { margin:0; font-size:15px; line-height:1.45; color:#fbe3cf; }
.clm-hero-side { position:relative; display:flex; align-items:center; gap:12px; flex-shrink:0; }
.clm-hero-stat {
  min-width:150px; padding:10px 18px; border-radius:8px; text-align:left;
  background:rgba(122,16,18,.92); border-left:4px solid #F3CE52;
}
.clm-hero-stat-v { font-size:34px; font-weight:700; line-height:1.1; letter-spacing:1px; color:#F3CE52; white-space:nowrap; }
.clm-hero-stat-k { margin-top:2px; font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.6px; color:#fbd9bd; }
.clm-hero-btn {
  display:inline-flex; align-items:center; gap:8px; padding:10px 18px; border:0; border-radius:6px;
  background:#F3CE52; color:#7A1012; font-size:14px; font-weight:700; cursor:pointer;
  box-shadow:0 0 0 2px #7A1012, 0 4px 12px rgba(0,0,0,.18);
}
.clm-hero-btn:hover { background:#ffe07a; }

/* Content panel, step tracker, sections */
.clm-nt-panel { margin-top:18px; background:#fff; border:1px solid #e0e6ed; border-radius:10px; overflow:hidden; }

.clm-nt-steps { display:flex; align-items:center; gap:10px; padding:16px 32px; background:#fafbfc; border-bottom:1px solid #dde3ea; }
.clm-nt-step { display:flex; align-items:center; gap:8px; flex-shrink:0; }
.clm-nt-step-n {
  width:26px; height:26px; border-radius:50%; display:inline-flex; align-items:center; justify-content:center;
  background:#eef1f5; border:1px solid #dde3ea; color:#7f8c9a; font-size:13px; font-weight:700;
}
.clm-nt-step-k { font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.6px; color:#7f8c9a; }
.clm-nt-step-line { flex:1; height:2px; min-width:20px; background:#e6eaef; }
.clm-nt-step.is-active .clm-nt-step-n { background:#F3D54E; border-color:#F3D54E; color:#1a1a1a; }
.clm-nt-step.is-active .clm-nt-step-k { color:#1a1a1a; }
.clm-nt-step.is-done .clm-nt-step-n { background:#1a1a1a; border-color:#1a1a1a; color:#F3D54E; }
.clm-nt-step.is-done .clm-nt-step-k { color:#3a4451; }

.clm-section { background:#fff; padding:28px 32px; border-top:1px solid #eef1f5; }
.clm-nt-steps + div > .clm-section:first-child,
.clm-nt-steps + .clm-section { border-top:0; }
.clm-nt-section-tight { padding-bottom:0; }
.clm-section-title {
  display:flex; align-items:center; gap:12px; margin-bottom:4px;
  font-size:14px; font-weight:700; color:#1a1a1a; text-transform:uppercase; letter-spacing:1px;
}
.clm-section-num {
  width:26px; height:26px; border-radius:50%; background:#F3D54E; color:#1a1a1a; flex-shrink:0;
  font-size:13px; font-weight:700; display:inline-flex; align-items:center; justify-content:center;
}

/* Card (block) + chips */
.clm-block { margin-top:16px; background:#fff; border:1px solid #dde3ea; border-radius:8px; overflow:hidden; }
.clm-block-head { display:flex; align-items:center; justify-content:space-between; gap:12px 20px; flex-wrap:wrap;
  padding:14px 20px; background:#fafbfc; border-bottom:1px solid #dde3ea; }
.clm-block-title { display:flex; align-items:center; gap:10px; font-size:14px; font-weight:700; color:#1a1a1a;
  text-transform:uppercase; letter-spacing:.9px; }
.clm-block-title::before { content:""; width:4px; height:16px; border-radius:2px; background:#F3D54E; flex-shrink:0; }
.clm-block-sub { margin:4px 0 0 14px; font-size:12px; color:#5a6a7a; }
.clm-block-meta { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.clm-chip { display:inline-flex; align-items:center; gap:6px; padding:4px 10px; background:#fff;
  border:1px solid #dde3ea; border-radius:12px; font-size:12px; font-weight:700; color:#1a1a1a; white-space:nowrap; }
.clm-chip-k { font-weight:400; color:#5a6a7a; }
.clm-chip-live { background:#eaf7ee; border-color:#b9e3c6; color:#1e8449; }
.clm-chip-req  { background:#fff8e1; border-color:#f3d54e; color:#7a5a00; }
.clm-chip-dev  { background:#fdecea; border-color:#f5c2bc; color:#b3261e; }
.clm-nt-dot { font-size:8px; }
.clm-tw-body { padding:18px 20px; }

/* small sub-heading inside a card body */
.clm-nt-sub-title { display:flex; align-items:center; gap:8px; margin-bottom:10px; font-size:12px; font-weight:700;
  text-transform:uppercase; letter-spacing:.6px; color:#3a4451; }
.clm-nt-sub-title::before { content:""; width:3px; height:12px; border-radius:2px; background:#F3D54E; }
.clm-nt-sub-gap { margin-top:22px; }

/* Forms */
.clm-field { display:flex; flex-direction:column; gap:6px; }
.clm-field-k { margin:0; font-size:13px; font-weight:700; color:#1a1a1a; }
.clm-field-hint { font-size:12px; color:#7f8c9a; }
.clm-req { color:#E23D28; font-weight:700; }
.clm-input.form-control { width:100%; display:block;
  height:auto; padding:9px 12px; font-size:14px; color:#1a1a1a; background:#fff;
  border:1px solid #cdd4dc; border-radius:6px; box-shadow:none; transition:border-color .2s, box-shadow .2s;
}
.clm-input.form-control:focus { border-color:#E8B800; box-shadow:0 0 0 3px rgba(243,213,78,.3); outline:0; }
.clm-nt-form-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px 20px; }
.clm-nt-span-2 { grid-column:1 / -1; }
.clm-nt-pan-input.form-control { font-size:16px; font-weight:700; letter-spacing:1px; text-transform:uppercase; padding:11px 42px 11px 14px; }

/* typeahead — in the page flow so the panel never clips it */
.clm-nt-typeahead-wrap { position:relative; }
.clm-nt-pan-box { position:relative; }
.clm-nt-pan-spin { position:absolute; right:14px; top:50%; transform:translateY(-50%); color:#7f8c9a; }
.clm-nt-typeahead {
  margin-top:4px; background:#fff; border:1px solid #dde3ea; border-radius:6px; overflow:hidden;
  box-shadow:0 8px 20px rgba(0,0,0,.06);
}
.clm-nt-ta-head { display:flex; align-items:center; justify-content:space-between; gap:10px;
  padding:8px 14px; background:#fafbfc; border-bottom:1px solid #e6eaef; font-size:12px; color:#5a6a7a; }
.clm-nt-ta-head strong { color:#1a1a1a; }
/* ~10 rows visible (≈42px each), the rest scroll */
.clm-nt-ta-list { margin:0; padding:0; list-style:none; max-height:420px; overflow-y:auto; overscroll-behavior:contain; }
.clm-nt-ta-list li + li { border-top:1px solid #f1f3f6; }
.clm-nt-ta-list li a { display:flex; align-items:center; gap:14px; min-height:42px; padding:9px 14px;
  text-decoration:none; color:#1a1a1a; }
.clm-nt-ta-list li a:hover, .clm-nt-ta-list li a:focus { background:#fffcf0; outline:0; }
.clm-nt-ta-pan { flex:0 0 120px; font-weight:700; letter-spacing:1px; }
.clm-nt-ta-name { flex:1; min-width:0; font-size:13px; color:#5a6a7a; text-transform:uppercase; }
.clm-nt-ta-go { font-size:11px; color:#b0b9c4; }
.clm-nt-ta-list li a:hover .clm-nt-ta-go { color:#1a1a1a; }
.clm-nt-ta-empty { margin-top:4px; padding:10px 14px; font-size:13px; color:#7f8c9a; background:#fafbfc;
  border:1px dashed #dde3ea; border-radius:6px; }

/* upload */
.clm-nt-upload { display:flex; align-items:center; gap:12px; padding:12px 14px; background:#fafbfc;
  border:1px dashed #c9d1db; border-radius:6px; }
.clm-nt-upload-ic { font-size:20px; color:#7f8c9a; }
.clm-nt-file-ok { font-size:13px; color:#1e8449; }

/* Data tables */
.clm-nt-table-scroll { overflow-x:auto; -webkit-overflow-scrolling:touch; }
.clm-table { width:100%; border-collapse:collapse; font-size:13px; font-variant-numeric:tabular-nums; margin:0; }
.clm-table th { background:#eef1f5; color:#2b3440; padding:12px 14px; font-size:12px; font-weight:700;
  text-transform:uppercase; letter-spacing:.6px; text-align:center; white-space:nowrap; border:1px solid #e3e8ee; vertical-align:middle; }
.clm-table td { padding:14px; color:#1a1a1a; text-align:center; white-space:nowrap; border:1px solid #edf0f4; vertical-align:middle; }
.clm-table tr > :first-child { border-left:0; }
.clm-table tr > :last-child  { border-right:0; }
.clm-table thead tr:first-child th { border-top:0; }
.clm-table tbody tr:last-child td  { border-bottom:0; }
.clm-table .grp { border-left:2px solid #dde3ea !important; }
.clm-table tr.super th { letter-spacing:1px; padding:11px 14px; }
.clm-table th.bg-blank  { background:#f7f8fa; }
.clm-table th.bg-code   { background:#e3eefa; color:#0b5394; }
.clm-table th.bg-pan    { background:#fdf3e1; color:#a35400; }
.clm-table th.bg-seg    { background:#f1f3f7; color:#3a4451; }
.clm-table th.bg-req    { background:#e6f4ea; color:#2e7d32; }
.clm-table th.bg-assess { background:#efe9f9; color:#6a3fb5; }
.clm-table .clm-nt-left { text-align:left; }

.clm-cust-name { font-weight:700; color:#1a1a1a; }
.clm-cust-code { margin-top:2px; font-size:12px; font-weight:600; color:#5a6a7a; }
.v-ok, .clm-table td.v-ok   { color:#1e8449; font-weight:700; }
.v-bad, .clm-table td.v-bad { color:#c0392b; font-weight:700; }
.clm-nt-strong { font-weight:700; }
.clm-nt-faint { color:#b0b9c4; }
.clm-nt-red { color:#c0392b; }
.clm-nt-wrap { white-space:normal; }

/* segment-wise credit position */
.clm-nt-seg-wrap { border:1px solid #dde3ea; border-radius:8px; }
.clm-nt-segtbl th, .clm-nt-segtbl td { padding:12px 16px; }
.clm-nt-segtbl .num { text-align:right; }
.clm-nt-segtbl td.clm-nt-ne { font-weight:700; background:#fffcf0; }
.clm-nt-segtbl tr.is-empty td { color:#9aa5b1; }
.clm-nt-segtbl tr.is-empty td.clm-nt-ne { background:transparent; font-weight:400; }
.clm-nt-segtbl tr.is-empty .clm-nt-seg { opacity:.6; }
.clm-nt-segtbl tfoot td { background:#f6f7f9; font-weight:700; border-top:2px solid #dde3ea; border-bottom:0; }
.clm-nt-segtbl tfoot td.clm-nt-left { text-transform:uppercase; letter-spacing:.6px; font-size:12px; color:#3a4451; }

/* step 1 site table */
.clm-nt-toolbar { padding:14px 20px; border-bottom:1px solid #e6eaef; }
.clm-nt-search { position:relative; max-width:420px; }
.clm-nt-search .fa { position:absolute; left:12px; top:50%; transform:translateY(-50%); color:#7f8c9a; }
.clm-nt-search .clm-input.form-control { padding-left:34px; }
.clm-nt-col-chk, .clm-nt-col-exp { width:44px; min-width:44px; max-width:44px; padding-left:8px !important; padding-right:8px !important; }

/* step 1 site table: checkbox, arrow and customer columns frozen while scrolling sideways */
.clm-nt-sites .clm-nt-stk { position:sticky; z-index:2; }
.clm-nt-sites thead .clm-nt-stk { z-index:3; }
.clm-nt-sites td.clm-nt-stk { background:#fff; }
.clm-nt-sites tr.clm-nt-row:hover td.clm-nt-stk { background:#fafbfc; }
.clm-nt-sites .clm-nt-stk-1 { left:0; }
.clm-nt-sites .clm-nt-stk-2 { left:44px; }
.clm-nt-sites .clm-nt-stk-3 { left:88px; box-shadow:6px 0 8px -6px rgba(26,26,26,.18); }
.clm-nt-sites .clm-nt-col-cust { min-width:260px; max-width:340px; white-space:normal; }
.clm-nt-cust-meta { display:flex; align-items:center; flex-wrap:wrap; gap:4px 6px; margin-top:4px; }
.clm-nt-cust-meta .clm-cust-code { margin-top:0; }
.clm-chip.clm-nt-chip-xs { padding:1px 8px; font-size:10.5px; border-radius:10px; }
.clm-nt-sites .clm-nt-col-terr { min-width:220px; white-space:normal; }
.clm-nt-terr-main { font-size:13px; font-weight:700; color:#1a1a1a; }
.clm-nt-terr-sub { margin-top:2px; font-size:12px; color:#5a6a7a; }
.clm-nt-checkbox { width:16px; height:16px; margin:0; cursor:pointer; accent-color:#1a1a1a; }
.clm-nt-exp-btn { width:28px; height:28px; padding:0; border:1px solid #dde3ea; border-radius:6px; background:#fff; color:#3a4451; cursor:pointer; }
.clm-nt-exp-btn:hover { background:#1a1a1a; color:#F3D54E; border-color:#1a1a1a; }
.clm-nt-seg { display:inline-block; padding:3px 10px; border-radius:12px; background:#f1f3f7; border:1px solid #dde3ea;
  font-size:11.5px; font-weight:700; color:#3a4451; }
.clm-nt-loc { font-size:12.5px; color:#3a4451; }
.clm-nt-row { cursor:pointer; transition:background .15s; }
.clm-nt-row:hover td { background:#fafbfc; }
.clm-table tr.selected-row td { background:#fffcf0 !important; }
.clm-table tr.selected-row td:first-child { box-shadow:inset 4px 0 0 #F3D54E; }
.clm-table tr.bg-light td { background:#f7f8fa !important; color:#9aa5b1; }
.clm-table tr.bg-light .clm-cust-name,
.clm-table tr.bg-light .v-ok,
.clm-table tr.bg-light .v-bad { color:#9aa5b1; }
.clm-table tr.bg-light { cursor:not-allowed; }

/* expanded ageing */
.clm-table tr.clm-nt-exp-row > td { padding:14px 16px; background:#f7f8fa; text-align:left; }
.clm-nt-exp-inner { position:sticky; left:16px; width:100%; max-width:min(940px, calc(100vw - 120px)); }
.clm-nt-exp-title { display:flex; align-items:center; gap:10px; margin-bottom:10px; font-size:12px; font-weight:700;
  text-transform:uppercase; letter-spacing:.6px; color:#3a4451; }
.clm-nt-exp-title::before { content:""; width:4px; height:14px; border-radius:2px; background:#F3D54E; }
.clm-nt-ag-wrap { border:1px solid #dde3ea; border-radius:6px; background:#fff; }
.clm-nt-ag { table-layout:fixed; }
.clm-nt-ag col.clm-nt-ag-c-month { width:104px; }
.clm-nt-ag col.clm-nt-ag-c-total { width:124px; }
.clm-nt-ag th { font-size:11px; padding:7px 8px; letter-spacing:.3px; }
.clm-nt-ag td { font-size:12px; padding:7px 8px; text-align:right; overflow:hidden; text-overflow:ellipsis; }
.clm-nt-ag td.clm-nt-left { text-align:left; }
.clm-nt-ag tr.ag-group th.safe { background:#d9eedd; color:#14532d; }  .clm-nt-ag tr.ag-sub th.safe { background:#edf7ef; color:#14532d; }
.clm-nt-ag tr.ag-group th.warn { background:#fde4c4; color:#7a4100; }  .clm-nt-ag tr.ag-sub th.warn { background:#fff4e5; color:#7a4100; }
.clm-nt-ag tr.ag-group th.risk { background:#f8d7d3; color:#8f1d16; }  .clm-nt-ag tr.ag-sub th.risk { background:#fdeeec; color:#8f1d16; }
.clm-nt-ag tr.ag-sub th:last-child { border-right:0; }
.clm-nt-ag td.zero { color:#b0b9c4; }
.clm-nt-ag td.warn-val { color:#a15a00; font-weight:700; background:#fffaf2; }
.clm-nt-ag td.risk-val { color:#b3261e; font-weight:700; background:#fff6f5; }
.clm-nt-empty { text-align:center !important; color:#7f8c9a; padding:14px !important; }

/* pager */
.clm-nt-pager { display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap;
  padding:12px 20px; background:#fafbfc; border-top:1px solid #dde3ea; }
.clm-nt-pagesize { display:flex; align-items:center; gap:8px; font-size:12.5px; color:#5a6a7a; }
.clm-nt-pagesize .clm-input.form-control { width:76px; padding:6px 8px; font-size:13px; }
.clm-nt-pagenav { display:flex; align-items:center; gap:10px; }
.clm-nt-pagenum { font-size:13px; font-weight:700; }

/* step 2 input grid */
.clm-nt-grid th { font-size:11px; padding:10px 7px; letter-spacing:.4px; white-space:normal; }
.clm-nt-grid td.clm-nt-left { white-space:normal; min-width:150px; }
.clm-nt-grid tr.super th { padding:9px 8px; }
.clm-nt-grid td { padding:10px 7px; }
.clm-nt-grid td.clm-nt-left { padding-left:14px; }
.clm-nt-cell.form-control { height:auto; width:84px; min-width:0; padding:7px 10px; font-size:13.5px; border:1px solid #cdd4dc;
  border-radius:5px; box-shadow:none; text-align:right; }
.clm-nt-cell.form-control:focus { border-color:#E8B800; box-shadow:0 0 0 3px rgba(243,213,78,.3); }
.clm-nt-cell.form-control[disabled] { background:#f1f3f7; color:#9aa5b1; }
.clm-nt-cell-sm.form-control { width:64px; }
.clm-nt-cell-key.form-control { width:112px; font-weight:700; background:#fffcf0; border-color:#e8d27a; }
.clm-nt-cell-txt.form-control { width:100%; min-width:140px; min-height:34px; text-align:left; resize:vertical; }
.clm-nt-calc { background:#faf8fe; text-align:right !important; }
.clm-nt-ro { background:#fdfaf3; color:#3a4451; }
.clm-table td.clm-nt-num { text-align:right; }
.clm-nt-unit { font-size:11px; font-weight:400; color:#7f8c9a; }
.clm-nt-grid td .clm-nt-err { max-width:120px; }
.clm-nt-grid tfoot td { background:#f6f7f9; font-weight:700; border-top:2px solid #dde3ea; border-bottom:0; padding:12px 8px; }
.clm-nt-grid tfoot td.clm-nt-left { padding-left:14px; text-transform:uppercase; letter-spacing:.6px; font-size:12px; color:#3a4451; }
/* step 2 grid: customer column frozen while scrolling sideways */
.clm-nt-grid .clm-nt-stk-g { position:sticky; left:0; z-index:2; min-width:200px; max-width:260px; white-space:normal;
  box-shadow:6px 0 8px -6px rgba(26,26,26,.18); }
.clm-nt-grid thead .clm-nt-stk-g { z-index:3; }
.clm-nt-grid tbody td.clm-nt-stk-g { background:#fff; }
.clm-nt-grid tfoot td.clm-nt-stk-g { background:#f6f7f9; }
.clm-nt-err { margin-top:4px; font-size:11px; font-weight:700; color:#c0392b; white-space:normal; text-align:left; }

/* step 4 review */
.clm-nt-rv th, .clm-nt-rv td { padding:12px 14px; }
.clm-nt-rv .num, .clm-table.clm-nt-rv td.num { text-align:right; }
.clm-nt-rv tr.is-empty td { color:#9aa5b1; }
.clm-nt-rv tr.is-empty .clm-nt-seg { opacity:.6; }
.clm-nt-rv tr.is-active td:first-child { box-shadow:inset 4px 0 0 #F3D54E; }
.clm-nt-rv tr.is-master td { background:#fcfcfd; }
.clm-nt-rv tr.is-master .clm-cust-name { color:#3a4451; }
.clm-nt-rv tfoot td { background:#f6f7f9; font-weight:700; border-top:2px solid #dde3ea; border-bottom:0; }
.clm-nt-rv tfoot td.clm-nt-left { text-transform:uppercase; letter-spacing:.6px; font-size:12px; color:#3a4451; }
.clm-table td.clm-nt-chg { background:#fffcf0; color:#7a4100; }
.clm-nt-inreq, .clm-nt-master { display:inline-block; margin-left:6px; padding:1px 7px; border-radius:10px; font-size:10.5px;
  font-weight:700; text-transform:uppercase; letter-spacing:.4px; vertical-align:middle; }
.clm-nt-inreq  { background:#1a1a1a; color:#F3D54E; }
.clm-nt-master { background:#f1f3f7; color:#5a6a7a; border:1px solid #dde3ea; }
.clm-nt-note-row { padding:12px 20px; font-size:12.5px; color:#3a4451; background:#fafbfc; border-top:1px solid #e6eaef; }
.clm-nt-seg-head { padding:12px 20px 8px; font-size:12.5px; color:#5a6a7a; }
.clm-nt-seg-head + .clm-nt-table-scroll { border-top:1px solid #e6eaef; }

.clm-nt-cmx th, .clm-nt-cmx td { padding:10px 20px; }
.clm-nt-cmx tfoot td, .clm-nt-cmx tr.clm-nt-cmx-tot td { background:#fff8e1; font-weight:700; color:#1a1a1a; border-top:1px solid #f1e2a0; }
.clm-nt-cmx tr.grp.clm-nt-ag-safe td { background:#edf7ef; color:#14532d; }
.clm-nt-cmx tr.grp.clm-nt-ag-warn td { background:#fff4e5; color:#7a4100; }
.clm-nt-cmx tr.grp.clm-nt-ag-risk td { background:#fdeeec; color:#8f1d16; }
.clm-nt-cmx .tag { margin-left:6px; }
.clm-nt-bar-col { width:200px; }
.clm-nt-bar { display:inline-block; width:90px; height:6px; margin-right:8px; vertical-align:middle; border-radius:3px; background:#e6eaef; overflow:hidden; }
.clm-nt-bar-fill { display:block; height:100%; border-radius:3px; }
.clm-nt-bar-safe { background:#1e8449; } .clm-nt-bar-warn { background:#e08a00; } .clm-nt-bar-risk { background:#c0392b; }

.clm-nt-res-tile { margin:0 20px 20px; padding:16px; text-align:center; border:1px solid #f1d77a; border-radius:8px; background:#fffcf0; }
.clm-block > .clm-nt-table-scroll + .clm-nt-res-tile,
.clm-block > div + .clm-nt-res-tile { margin-top:16px; }
.clm-nt-res-tile-k { font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.8px; color:#7a5a00; }
.clm-nt-res-tile-v { margin-top:4px; font-size:28px; font-weight:700; color:#1a1a1a; }

.clm-tw-factors.clm-nt-rating-tiles { grid-template-columns:repeat(2,minmax(0,1fr)); }
.clm-nt-rating { text-align:center; }
.clm-nt-rating-v { font-size:30px; font-weight:700; line-height:1.2; color:#1a1a1a; }

.clm-nt-safe { border-color:#f1d77a; }
.clm-chip.clm-nt-chip-wrap { white-space:normal; }
.clm-nt-eq { display:grid; grid-template-columns:minmax(0,1fr) auto minmax(0,1fr) auto minmax(0,1fr) auto minmax(0,1.1fr); gap:12px; align-items:center; }
.clm-nt-eq-op { font-size:20px; font-weight:700; color:#7f8c9a; text-align:center; }
.clm-nt-eq .clm-tw-factor-v { font-size:18px; }
.clm-nt-eq .clm-tw-factor.is-ok { border-color:#1e8449; }

/* Step 4 MACL table grouped by segment */
.clm-nt-macl tr.clm-nt-segrow td { background:#f6f7f9; font-weight:700; color:#1a1a1a; border-top:1px solid #e3e8ee; }
.clm-nt-segrow-k { margin-left:8px; font-size:12px; font-weight:400; color:#5a6a7a; }
.clm-table td.clm-nt-indent { padding-left:28px; }

/* Step 4 MACL: Requested sites / All sites toggle */
.clm-nt-toggle { display:inline-flex; border:1px solid #cdd4dc; border-radius:16px; overflow:hidden; background:#fff; }
.clm-nt-toggle-btn { padding:5px 14px; border:0; background:transparent; color:#3a4451; font-size:12px; font-weight:700; cursor:pointer; white-space:nowrap; }
.clm-nt-toggle-btn + .clm-nt-toggle-btn { border-left:1px solid #cdd4dc; }
.clm-nt-toggle-btn:hover { background:#f6f7f9; }
.clm-nt-toggle-btn.is-on { background:#1a1a1a; color:#F3D54E; }

/* Step 4 credit index: ageing on the left, ratings and credit index on the right */
.clm-nt-credit-grid { display:grid; grid-template-columns:minmax(0,1.7fr) minmax(260px,1fr); gap:16px; padding:16px 20px 20px; align-items:start; }
.clm-nt-credit-main { border:1px solid #dde3ea; border-radius:8px; overflow:hidden; }
.clm-nt-credit-side { display:flex; flex-direction:column; gap:12px; }
.clm-nt-credit-side .clm-tw-factor { padding:14px 16px; }
.clm-nt-credit-grid + .clm-nt-res-tile { margin-top:0; }
/* rating letters: A green, B orange, C red */
.clm-nt-rating-v.grade-A { color:#1e8449; }
.clm-nt-rating-v.grade-B { color:#e07b00; }
.clm-nt-rating-v.grade-C { color:#c0392b; }

/* Step 4 composite index (P2) */
.clm-nt-step-dot { display:inline-flex; align-items:center; justify-content:center; width:20px; height:20px; margin-right:4px;
  border-radius:50%; background:#1a1a1a; color:#F3D54E; font-size:11px; font-weight:700; vertical-align:middle; }
.clm-nt-table-scroll + .clm-nt-seg-head { padding-top:16px; border-top:1px solid #e6eaef; }
.clm-nt-th-sub { margin-top:2px; font-size:10px; font-weight:400; text-transform:none; letter-spacing:0; color:#7f8c9a; }
.clm-nt-sub-v { margin-top:2px; font-size:11px; font-weight:400; color:#7f8c9a; }
.clm-nt-segp td.clm-nt-segcell { background:#fafbfc; border-right:1px solid #e6eaef; vertical-align:middle; }
.clm-nt-segp tr.seg-first td { border-top:2px solid #e6eaef; }
.clm-nt-segp tbody tr:first-child td { border-top:0; }
.clm-nt-p2w th, .clm-nt-p2w td { padding:10px 12px; }


/* Matrix (step 3) */
.clm-matrix { width:100%; border-collapse:collapse; font-size:13px; margin:0; }
.clm-matrix th { text-align:left; padding:12px 14px; background:#e4e9f0; color:#1a1a1a; font-size:12px;
  font-weight:700; text-transform:uppercase; letter-spacing:.7px; border:1px solid #d9e0e8; }
.clm-matrix td { padding:11px 14px; border:1px solid #edf0f4; color:#1a1a1a; vertical-align:middle; }
.clm-matrix tr > :first-child { border-left:0; }
.clm-matrix tr > :last-child  { border-right:0; }
.clm-matrix thead tr:first-child th { border-top:0; }
.clm-matrix tbody:last-of-type tr:last-child td, .clm-matrix tfoot tr:last-child td { border-bottom:0; }
.clm-matrix .num { text-align:right; white-space:nowrap; }
.clm-matrix tr.grp td { background:#fbf6e4; color:#1a1a1a; padding:10px 14px; font-size:12.5px; font-weight:700;
  text-transform:uppercase; letter-spacing:.9px; border-top:1px solid #efe3b8; border-bottom:1px solid #efe3b8; }
.clm-matrix tr.grp td:first-child { box-shadow:inset 4px 0 0 #F3D54E; }
.clm-nt-m-name { width:42%; } .clm-nt-m-sel { width:40%; } .clm-nt-m-src { width:18%; }
.clm-nt-m-title { font-size:13px; font-weight:600; color:#2b3440; }
.clm-nt-m-select.form-control { padding:7px 10px; font-size:13px; }
.clm-nt-m-src-val { margin-top:3px; font-size:11.5px; color:#5a6a7a; }
.clm-nt-m-src-val.is-ai .fa { color:#1782c5; }
.clm-nt-m-src-val.is-input .fa { color:#800080; }
.clm-nt-m-orig { margin-top:4px; font-size:11px; color:#7f8c9a; }
.clm-matrix tbody tr:not(.grp):hover td { background:#fcfcfd; }
.clm-matrix tr.ai-highlight-row td    { background:#f7fbfe; }
.clm-matrix tr.ai-highlight-row td:first-child    { box-shadow:inset 4px 0 0 #1782c5; }
.clm-matrix tr.input-highlight-row td { background:#fcf9ff; }
.clm-matrix tr.input-highlight-row td:first-child { box-shadow:inset 4px 0 0 #800080; }
.clm-matrix tr.edit-highlight-row td  { background:#fffdf6; }
.clm-matrix tr.edit-highlight-row td:first-child  { box-shadow:inset 4px 0 0 #ffc107; }
.clm-matrix tr.default-param-row td   { background:#fafbfc; }
.clm-matrix tr.default-param-row td:first-child   { box-shadow:inset 4px 0 0 #b0b9c4; }
.clm-matrix tr.grp td.clm-nt-m-gmeta { font-weight:600; text-transform:none; letter-spacing:0; color:#7a5a00; font-size:12px; }
.clm-nt-m-def { margin-top:5px; font-size:11.5px; color:#5a6a7a; }

.tag { display:inline-flex; align-items:center; gap:4px; padding:2px 8px; border-radius:4px; border:1px solid; font-size:10.5px; font-weight:700; white-space:nowrap; }
.tag-ai     { background:#eef6fb; color:#1782c5; border-color:#1782c5; }
.tag-input  { background:#f6eefe; color:#800080; border-color:#800080; }
.tag-ovr    { background:#fffbeb; color:#a07000; border-color:#ffc107; }
.tag-manual { background:#f5f5f5; color:#5a6a7a; border-color:#d6dbe1; }
.tag-miss   { background:#fdecea; color:#b3261e; border-color:#f5c2bc; }
.tag-default { background:#f1f3f7; color:#3a4451; border-color:#b0b9c4; }

.border-danger { border-color:#E23D28 !important; box-shadow:0 0 0 3px rgba(226,61,40,.12) !important; }

/* Factor tiles + result row */
.clm-tw-factors { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:12px; }
.clm-nt-factors-4 { grid-template-columns:repeat(4,minmax(0,1fr)); }
.clm-tw-factor { padding:12px 14px; border:1px solid #e0e6ed; border-radius:6px; background:#fafbfc; }
.clm-tw-factor-k { font-size:12px; color:#5a6a7a; margin-bottom:4px; }
.clm-tw-factor-v { font-size:16px; font-weight:700; color:#1a1a1a; white-space:nowrap; }
.clm-nt-head-v { font-size:20px; }
.clm-tw-factor-s { font-size:11px; color:#7f8c9a; margin-top:4px; }
.clm-tw-factor.is-ok  { background:#f4fbf6; border-color:#cfead8; }  .clm-tw-factor.is-ok  .clm-tw-factor-v { color:#1e8449; }
.clm-tw-factor.is-bad { background:#fef5f4; border-color:#f5c2bc; }  .clm-tw-factor.is-bad .clm-tw-factor-v { color:#c0392b; }
.clm-tw-factor.is-key { background:#fffcf0; border-color:#f1e2a0; box-shadow:inset 4px 0 0 #F3D54E; }

.clm-tw-res { display:flex; align-items:center; justify-content:space-between; gap:12px 20px; flex-wrap:wrap;
  padding:16px 20px; background:#fffcf0; border-top:1px solid #f1e2a0; }
.clm-tw-res-k { font-size:13px; font-weight:700; color:#3a4451; text-transform:uppercase; letter-spacing:.6px; }
.clm-tw-res-f { margin-top:6px; font-size:12px; color:#7f8c9a; }
.clm-tw-res-v { margin-left:auto; font-size:30px; font-weight:700; line-height:1.1; color:#1a1a1a; }
.clm-tw-res.is-ok  { background:#f4fbf6; border-top-color:#b9e3c6; } .clm-tw-res.is-ok  .clm-tw-res-v { color:#1e8449; }
.clm-tw-res.is-bad { background:#fef5f4; border-top-color:#f5c2bc; } .clm-tw-res.is-bad .clm-tw-res-v { color:#c0392b; }

/* Notices, loaders, actions, buttons, success */
.clm-note { display:flex; align-items:flex-start; gap:10px; margin-top:16px; padding:12px 16px; border:1px solid; border-radius:8px; font-size:13px; }
.clm-note .fa { margin-top:2px; }
.clm-note-ok   { background:#f4fbf6; border-color:#b9e3c6; color:#1e8449; }
.clm-note-warn { background:#fff8e1; border-color:#f3d54e; color:#7a5a00; }
.clm-note-err  { background:#fef5f4; border-color:#f5c2bc; color:#c0392b; margin-top:0; }

.clm-nt-loader { padding:36px 20px; text-align:center; }
.clm-nt-loader .fa { color:#AF272F; margin-bottom:14px; }
.clm-nt-loader-t { font-size:16px; font-weight:700; color:#1a1a1a; }
.clm-nt-loader-s { margin-top:6px; font-size:12.5px; color:#5a6a7a; }

.clm-nt-actions { display:flex; align-items:center; justify-content:flex-end; gap:10px; flex-wrap:wrap;
  padding:18px 32px; background:#fafbfc; border-top:1px solid #dde3ea; }
.clm-nt-busy { margin-right:auto; font-size:12.5px; color:#5a6a7a; }

.clm-btn { display:inline-flex; align-items:center; justify-content:center; gap:8px; padding:10px 20px;
  background:#fff; color:#1a1a1a; border:1px solid #cdd4dc; border-radius:6px; font-size:13px; font-weight:700;
  text-transform:uppercase; letter-spacing:.5px; cursor:pointer; white-space:nowrap; transition:background .2s, color .2s, border-color .2s; }
.clm-btn:hover { border-color:#1a1a1a; }
.clm-btn-sm { padding:6px 12px; font-size:12px; }
.clm-btn-primary { background:#1a1a1a; color:#F3D54E; border-color:#1a1a1a; }
.clm-btn-primary:hover { background:#333; color:#F3D54E; }
.clm-btn[disabled], .clm-btn[disabled]:hover { background:#eef1f5; color:#9aa5b1; border-color:#dde3ea; cursor:not-allowed; }

.clm-nt-success { padding:48px 32px; text-align:center; border-top:0; }
.clm-nt-success-ic { width:72px; height:72px; margin:0 auto 16px; border-radius:50%; display:flex; align-items:center; justify-content:center;
  background:#eaf7ee; border:2px solid #27ae60; color:#27ae60; font-size:32px; }
.clm-nt-success-t { font-size:20px; font-weight:700; color:#1a1a1a; }
.clm-nt-success-s { margin:8px auto 24px; max-width:520px; font-size:13.5px; color:#5a6a7a; }
.clm-nt-success-actions { display:flex; justify-content:center; gap:10px; flex-wrap:wrap; }

.slide-down { animation:clmNtSlide .35s ease-out; }
@keyframes clmNtSlide { from { opacity:0; transform:translateY(-8px); } to { opacity:1; transform:translateY(0); } }

/* Responsive */
@media (max-width:1100px) {
  .clm-nt-factors-4 { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .clm-tw-factors { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .clm-hero-title { font-size:22px; }
}
@media (max-width:900px) {
  .clm-nt-eq { grid-template-columns:1fr; gap:6px; }
  .clm-nt-credit-grid { grid-template-columns:1fr; }
  .clm-nt-eq-op { line-height:1; }
}
@media (max-width:768px) {
  .clm-nt-page { padding:14px; }
  .clm-hero { flex-direction:column; align-items:flex-start; padding:22px 20px 70px; }
  .clm-hero::after { background:linear-gradient(180deg, #7A1012 0%, #9E1715 55%, rgba(158,23,21,.55) 75%, rgba(122,16,18,0) 100%); }
  .clm-hero-sun { left:50%; }
  .clm-hero-side { width:100%; }
  .clm-section { padding:20px 16px; }
  .clm-nt-steps { padding:12px 16px; overflow-x:auto; }
  .clm-nt-step-k { display:none; }
  .clm-nt-step.is-active .clm-nt-step-k { display:inline; }
  .clm-nt-actions { padding:14px 16px; }
  .clm-nt-form-grid { grid-template-columns:1fr; }
  .clm-nt-ta-list li a { flex-wrap:wrap; gap:2px 10px; }
  .clm-nt-ta-pan { flex-basis:auto; }
  .clm-nt-ta-name { flex-basis:100%; order:3; }
  .clm-nt-ta-go { margin-left:auto; }
  .clm-nt-ta-list { max-height:360px; }
}
@media (max-width:640px) {
  .clm-hero-title { font-size:20px; }
  .clm-hero-sub { font-size:13px; }
  .clm-hero-stat-v { font-size:28px; }
  .clm-nt-factors-4, .clm-tw-factors { grid-template-columns:1fr; gap:8px; }
  .clm-tw-factor { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:4px 10px; }
  .clm-tw-factor-k { margin-bottom:0; }
  .clm-tw-factor-s { flex-basis:100%; margin-top:0; }
  .clm-nt-head-v { font-size:16px; }
  .clm-tw-res-v { font-size:24px; margin-left:0; }
  .clm-block-sub { margin-left:0; }
  .clm-nt-actions .clm-btn, .clm-nt-success-actions .clm-btn { width:100%; }
  .clm-nt-busy { width:100%; }
  .clm-nt-pager { flex-direction:column; align-items:stretch; }
  .clm-nt-pagenav { justify-content:space-between; }
  .clm-nt-segtbl th, .clm-nt-segtbl td { padding:10px 12px; }
  .clm-tw-factors.clm-nt-rating-tiles { grid-template-columns:1fr; }
  .clm-tw-factor.clm-nt-rating { display:block; }
  .clm-nt-credit-grid { padding:12px; }
  .clm-nt-cmx th, .clm-nt-cmx td { padding:9px 12px; }
  .clm-nt-bar { width:50px; }
}

/* One font family (keep last) */
.clm-widget, .clm-widget *, .clm-widget input, .clm-widget select,
.clm-widget textarea, .clm-widget button, .clm-widget table {
  font-family: "Oxygen", "Source Sans Pro", "Helvetica Neue", Helvetica, Arial, sans-serif !important;
}
.clm-widget .fa { font-family: FontAwesome !important; }

sp_widget.script:
(function() {
	if (!input) return;

	var CONFIG = {
		TABLES: {
			CUSTOMER:        'x_birl3_clm_clm_customer_master1',
			PAN_REQUEST:     'x_birl3_clm_nt_pan_request',
			PAN_OUTSTANDING: 'x_birl3_clm_nt_pan_request_outstanding',
			SITE_REQUEST:    'x_birl3_clm_nt_site_request',
			LIMIT_SWAP:      'x_birl3_clm_nt_limit_swap_request',
			CUSTOMER_FORM:   'x_birl3_clm_customer_form',
			OUTSTANDING:     'x_birl3_clm_clm_aging_snapshot',
			SALES_VALUE:     'x_birl3_clm_clm_cement_rmc_bpd_values',
			RISK_MATRIX:     'x_birl3_clm_risk_parameter_matrix',
			REQ_PARAMS:      'x_birl3_clm_request_parameters',
			MATRIX:          'x_birl3_clm_approval_matrix',
			OCR_CRIF:        'x_birl3_clm_ocr_test',
			OCR_BS:          'x_birl3_clm_bs_ocr',
			OCR_CORP:        'x_birl3_clm_corpository_ocr'
		},
		// Step 2 prefill: customer form first, then customer master (field by field; empty or 0 falls through)
		FORM_FIELDS: {
			potential:   'site_total_potential',
			currentQty:  'site_ut_sob',
			expectedQty: 'site_expected_sob',
			tenor:       'credit_tenor',
			rate:        'rate'
		},
		MASTER_FIELDS: {
			potential:   'total_potential',
			currentQty:  'current_potential',
			expectedQty: 'expected_potential',
			tenor:       'credit_tenor',
			rate:        'rate'
		},
		STANDARD_MONTHS: ['apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec', 'jan', 'feb', 'mar'],
		DEFAULT_CREDIT_TENOR: 45,
		MAX_UPLOAD_BYTES: 5 * 1024 * 1024,
		MAX_PAN_SUGGESTIONS: 25,
		PAN_SUGGESTION_SCAN: 1000,
		// P2 weighting: each segment's index is weighted by MPQ x average order rate of its sites.
		// 'simple'    = plain average of the order rates of the segment's sites (sites with no rate are skipped)
		// 'potential' = average weighted by each site's potential
		AVG_RATE_MODE: 'simple',
		RATING_BANDS: {
			A: ['AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-'],
			B: ['BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-'],
			C: ['BB-', 'B+', 'B', 'B-', 'CCC', 'CC', 'C', 'D']
		},
		P3_GRID: {
			'A': { 'A': 1.00, 'B': 0.75, 'C': 0.00 },
			'B': { 'A': 0.75, 'B': 0.60, 'C': 0.00 },
			'C': { 'A': 0.00, 'B': 0.00, 'C': 0.00 }
		}
	};

	var SEGMENTS = ['Cement', 'RMC', 'BPD'];

	// Generic helpers
	function safeAttach(gr, fileName, fileType, fileData) {
		try {
			new GlideSysAttachment().writeBase64(gr, fileName, fileType, fileData);
			return true;
		} catch (e) {
			gs.error('Attachment failed for ' + fileName + ': ' + e.message);
			return false;
		}
	}

	function getSafeValue(gr, fieldsArray) {
		for (var i = 0; i < fieldsArray.length; i++) {
			if (gr.isValidField(fieldsArray[i])) {
				var val = gr.getValue(fieldsArray[i]);
				if (val !== null && val !== undefined && val.toString().trim() !== '') {
					return val.toString().trim();
				}
			}
		}
		return '';
	}

	function getOptionalNumeric(gr, field) {
		if (!gr.isValidField(field)) return null;
		var v = gr.getValue(field);
		return (v !== '' && v !== null && v !== undefined) ? parseFloat(v) : null;
	}

	function getOptionalString(gr, field) {
		return gr.isValidField(field) ? (gr.getValue(field) || '') : '';
	}

	function isBlankVal(v) {
		return v === null || v === undefined || v === '';
	}

	function round2(n) {
		return Math.round((parseFloat(n) || 0) * 100) / 100;
	}

	function formatLocation(code, name) {
		code = code || '';
		name = name || '';
		if (name && code) return name + ' (' + code + ')';
		return name || code;
	}

	function getSobFigures(row) {
		var pot = parseFloat(row.totalPotential) || 0;
		var curQty = !isBlankVal(row.currentSob)
		? (parseFloat(row.currentSob) || 0)
		: pot * ((parseFloat(row.currentSobPct) || 0) / 100);
		var expQty = !isBlankVal(row.expectedSob)
		? (parseFloat(row.expectedSob) || 0)
		: pot * ((parseFloat(row.expectedSobPct) || 0) / 100);
		return {
			pot:    pot,
			curQty: curQty,
			expQty: expQty,
			curPct: pot > 0 ? round2((curQty / pot) * 100) : 0,
			expPct: pot > 0 ? round2((expQty / pot) * 100) : 0
		};
	}

	function validateSob(row) {
		var f = getSobFigures(row);
		if (f.pot < 0 || f.curQty < 0 || f.expQty < 0) return 'Site ' + row.code + ': Potential / SOB cannot be negative.';
		if (f.curQty > f.pot) return 'Site ' + row.code + ': Current SOB cannot exceed Potential.';
		if (f.expQty > f.pot) return 'Site ' + row.code + ': Expected SOB cannot exceed Potential.';
		return '';
	}

	// NOD (cement only, table based)
	function calculateSiteNOD(custSysId, custCode, segment, tableOs) {
		if (!segment || segment.toLowerCase().indexOf('cement') === -1) {
			return 0;
		}

		var p1 = 0;
		if (tableOs !== undefined && tableOs !== null && !isNaN(tableOs)) {
			p1 = Math.abs(parseFloat(tableOs)) || 0;
		} else {
			var snap = new GlideRecord(CONFIG.TABLES.OUTSTANDING);
			var sq = snap.addQuery('customer', custSysId);
			if (custCode) {
				sq.addOrCondition('customer.customer_code_sap', custCode);
				sq.addOrCondition('customer', custCode);
			}
			snap.orderByDesc('snapshot_month');
			snap.setLimit(1);
			snap.query();
			if (snap.next()) {
				p1 = Math.abs(parseFloat(snap.getValue('total_outstanding') || snap.getValue('u_net_balance'))) || 0;
			}
		}

		var totalSales = 0;
		var valGr = new GlideRecord(CONFIG.TABLES.SALES_VALUE);
		var vq = valGr.addQuery('u_customer', custSysId);
		if (custCode) {
			vq.addOrCondition('u_customer.customer_code_sap', custCode);
			vq.addOrCondition('u_customer', custCode);
		}
		valGr.orderByDesc('sys_created_on');
		valGr.setLimit(1);
		valGr.query();

		if (valGr.next()) {
			CONFIG.STANDARD_MONTHS.forEach(function(m) {
				var val = valGr.isValidField(m) ? valGr.getValue(m) : valGr.getValue('u_' + m);
				totalSales += parseFloat(val) || 0;
			});
		}
		var p2 = totalSales / 12;

		return p2 > 0 ? Math.round((p1 / p2) * 30) : 0;
	}

	function snapshotPanLevelAgingBuckets(panRequestSysId, panValue) {
		if (!panRequestSysId || !panValue) return;

		var custGr = new GlideRecord(CONFIG.TABLES.CUSTOMER);
		custGr.addQuery('pan', panValue);
		custGr.query();

		while (custGr.next()) {
			var siteSysId = custGr.getUniqueValue();
			var siteCode  = custGr.getValue('customer_code_sap');

			var snapGr = new GlideRecord(CONFIG.TABLES.OUTSTANDING);
			var sq = snapGr.addQuery('customer', siteSysId);
			if (siteCode) {
				sq.addOrCondition('customer.customer_code_sap', siteCode);
				sq.addOrCondition('customer', siteCode);
			}
			snapGr.orderByDesc('snapshot_month');
			snapGr.setLimit(6);
			snapGr.query();

			while (snapGr.next()) {
				var b0_21   = parseFloat(snapGr.getValue('bucket_0_21_days')   || snapGr.getValue('bucket_0_30_days'))   || 0;
				var b22_30  = parseFloat(snapGr.getValue('bucket_22_30_days'))  || 0;
				var b31_45  = parseFloat(snapGr.getValue('bucket_31_45_days'))  || 0;
				var b46_60  = parseFloat(snapGr.getValue('bucket_46_60_days'))  || 0;
				var b61_75  = parseFloat(snapGr.getValue('bucket_61_75_days'))  || 0;
				var b76_90  = parseFloat(snapGr.getValue('bucket_76_90_days'))  || 0;
				var b91_120 = parseFloat(snapGr.getValue('bucket_91_120_days')) || 0;
				var b121_180 = parseFloat(snapGr.getValue('bucket_121_180_days')) || 0;
				var b181_365 = parseFloat(snapGr.getValue('bucket_181_365_days')) || 0;
				var b366_730 = parseFloat(snapGr.getValue('bucket_366_730_days')) || 0;
				var b730_above = parseFloat(snapGr.getValue('bucket_730_days_above')) || 0;
				var b_gt120 = parseFloat(snapGr.getValue('bucket_gt120_days')) || (b121_180 + b181_365 + b366_730 + b730_above);

				var rawTotalOs = snapGr.getValue('total_outstanding') || snapGr.getValue('u_net_balance');
				var computedTotalOs = (rawTotalOs !== null && rawTotalOs !== '')
				? Math.abs(parseFloat(rawTotalOs))
				: Math.abs(b0_21 + b22_30 + b31_45 + b46_60 + b61_75 + b76_90 + b91_120 + b_gt120);

				var panOsGr = new GlideRecord(CONFIG.TABLES.PAN_OUTSTANDING);
				panOsGr.initialize();
				panOsGr.setValue('pan_request',            panRequestSysId);
				panOsGr.setValue('customer_site_code',     siteSysId);
				panOsGr.setValue('snapshot_month',         snapGr.getValue('snapshot_month'));
				panOsGr.setValue('total_outstanding',      computedTotalOs);
				panOsGr.setValue('bucket_0_21_days',       b0_21);
				panOsGr.setValue('bucket_22_30_days',      b22_30);
				panOsGr.setValue('bucket_31_45_days',      b31_45);
				panOsGr.setValue('bucket_46_60_days',      b46_60);
				panOsGr.setValue('bucket_61_75_days',      b61_75);
				panOsGr.setValue('bucket_76_90_days',      b76_90);
				panOsGr.setValue('bucket_91_120_days',     b91_120);
				panOsGr.setValue('bucket_121_180_days',    b121_180);
				panOsGr.setValue('bucket_181_365_days',    b181_365);
				panOsGr.setValue('bucket_366_730_days',    b366_730);
				panOsGr.setValue('bucket_730_days_above',  b730_above);
				panOsGr.setValue('bucket_gt120_days',      b_gt120);

				panOsGr.insert();
			}
		}
	}

	// Thresholds
	function getThresholds() {
		return {
			cement:       parseFloat(gs.getProperty('x_birl3_clm.threshold.cement', '5000000')),
			rmc:          parseFloat(gs.getProperty('x_birl3_clm.threshold.rmc', '2500000')),
			bpd:          parseFloat(gs.getProperty('x_birl3_clm.threshold.bpd', '2500000')),
			defaultSeg:   parseFloat(gs.getProperty('x_birl3_clm.threshold.default', '2500000')),
			crossSegment: parseFloat(gs.getProperty('x_birl3_clm.threshold.cross_segment', '15000000'))
		};
	}

	function getToolWorkingThreshold(segment, thresholds) {
		if (segment === 'Cement') return thresholds.cement;
		if (segment === 'RMC')    return thresholds.rmc;
		if (segment === 'BPD')    return thresholds.bpd;
		return thresholds.defaultSeg;
	}

	// Risk matrix parameters
	function loadMatrixParameters() {
		data.groupedParameters = {};
		var paramMap = {};
		var grMatrix = new GlideRecord(CONFIG.TABLES.RISK_MATRIX);
		grMatrix.orderBy('category');
		grMatrix.orderBy('parameter_name');
		grMatrix.orderBy('order');
		grMatrix.query();

		while (grMatrix.next()) {
			var catName = grMatrix.getValue('category');
			var pName   = grMatrix.getValue('parameter_name');

			if (!data.groupedParameters[catName]) {
				data.groupedParameters[catName] = [];
			}
			if (!paramMap[pName]) {
				paramMap[pName] = {
					name:          pName,
					segmentTag:    getOptionalString(grMatrix, 'segment_tag'),
					options:       [],
					selectedValue: '',
					autoMapped:    false,
					isChanged:     false,
					originalValue: '',
					originalLabel: ''
				};
				data.groupedParameters[catName].push(paramMap[pName]);
			}
			paramMap[pName].options.push({
				sys_id:   grMatrix.getUniqueValue(),
				label:    grMatrix.getValue('option_label'),
				score:    parseFloat(grMatrix.getValue('score_value')) || 0,
				weight:   parseFloat(grMatrix.getValue('weight_percentage')) || 0,
				operator: getOptionalString(grMatrix, 'operator'),
				minValue: getOptionalNumeric(grMatrix, 'min_value'),
				maxValue: getOptionalNumeric(grMatrix, 'max_value')
			});
		}
	}

	function isParamRelevant(param, segment) {
		var tag = (param.segmentTag || '').trim();
		if (tag) return tag === 'All' || tag === segment;

		var name = (param.name || '').toLowerCase();
		var isCem = name.indexOf('cement') !== -1;
		var isRmc = name.indexOf('rmc') !== -1;
		var isBpd = name.indexOf('bpd') !== -1;
		if (!isCem && !isRmc && !isBpd) return true;
		if (isCem && segment === 'Cement') return true;
		if (isRmc && segment === 'RMC') return true;
		if (isBpd && segment === 'BPD') return true;
		return false;
	}

	function isShareOrSobParam(pNameLower) {
		return pNameLower.indexOf('share') !== -1 || pNameLower.indexOf('sob') !== -1;
	}

	function isPotentialParam(pNameLower) {
		return pNameLower.indexOf('potential') !== -1;
	}

	function isPanWideParam(param) {
		var tag = (param.segmentTag || '').trim();
		if (tag) return tag === 'All';
		var name = (param.name || '').toLowerCase();
		return name.indexOf('cement') === -1 && name.indexOf('rmc') === -1 && name.indexOf('bpd') === -1;
	}

	function segKey(t) {
		t = (t || '').toString().toLowerCase();
		if (t.indexOf('cement') !== -1) return 'Cement';
		if (t.indexOf('rmc') !== -1) return 'RMC';
		if (t.indexOf('bpd') !== -1) return 'BPD';
		return null;
	}

	function effectiveTenorForMaster(v) {
		var t = parseInt(v, 10);
		return (t > 0) ? t : CONFIG.DEFAULT_CREDIT_TENOR;
	}

	// All sites under the PAN: request values for selected sites, CUSTOMER MASTER values for the rest
	function buildPanSiteRows(isListed) {
		var picked = {};
		(input.selectedCustomers || []).forEach(function(sc) { picked[sc.code] = sc; });

		return (input.customers || []).map(function(cust) {
			var sel = picked[cust.code];
			var src = sel || {
				totalPotential: cust.masterPotential,
				currentSob:     cust.masterCurrentSob,
				expectedSob:    cust.masterExpectedSob,
				orderRate:      cust.masterRate,
				creditTenor:    cust.masterTenor
			};
			var sob = getSobFigures(src);
			var rate = parseFloat(src.orderRate) || 0;
			var tenor = sel
			? (isBlankVal(src.creditTenor) ? CONFIG.DEFAULT_CREDIT_TENOR : (parseInt(src.creditTenor, 10) || 0))
			: effectiveTenorForMaster(src.creditTenor);
			var macl = isListed ? 0 : sob.expQty * rate * (tenor / 30);
			if (isNaN(macl) || macl < 0) macl = 0;
			var curCl = parseFloat(cust.limit) || 0;

			return {
				code: cust.code, name: cust.name, segment: cust.segmentDisplay,
				segKey: segKey(cust.segmentDisplay) || segKey(cust.segmentValue),
				inRequest: !!sel,
				hasInputs: !!(sob.pot || sob.expQty || rate),
				potential: sob.pot, currentSob: sob.curQty, expectedSob: sob.expQty,
				currentSobPct: sob.curPct, expectedSobPct: sob.expPct,
				orderRate: rate, creditTenor: tenor, macl: macl,
				currentCl: curCl,
				updatedCl: sel ? (parseFloat(sel.desiredLimit) || 0) : curCl,
				activeBg: parseFloat(cust.activeBg) || 0
			};
		});
	}

	function sumBy(rows, key) {
		return rows.reduce(function(t, r) { return t + (parseFloat(r[key]) || 0); }, 0);
	}

	// Segment position rows: segments with no customer site are left out
	function buildSegmentRows(siteRows) {
		var rows = SEGMENTS.map(function(k) {
			var segSites = siteRows.filter(function(r) { return r.segKey === k; });
			var cur = sumBy(segSites, 'currentCl'), bg = sumBy(segSites, 'activeBg'), upd = sumBy(segSites, 'updatedCl');
			return {
				segment: k, sites: segSites.length,
				inRequest: segSites.filter(function(r) { return r.inRequest; }).length,
				currentLimit: cur, activeBg: bg, currentNe: cur - bg,
				updatedLimit: upd, updatedNe: upd - bg
			};
		}).filter(function(r) { return r.sites > 0; });
		var tCur = sumBy(siteRows, 'currentCl'), tBg = sumBy(siteRows, 'activeBg'), tUpd = sumBy(siteRows, 'updatedCl');
		return {
			rows: rows,
			total: {
				sites: siteRows.length, inRequest: siteRows.filter(function(r) { return r.inRequest; }).length,
				currentLimit: tCur, activeBg: tBg, currentNe: tCur - tBg, updatedLimit: tUpd, updatedNe: tUpd - tBg
			}
		};
	}

	function getLowestOption(param) {
		var best = null;
		var opts = (param && param.options) || [];
		for (var i = 0; i < opts.length; i++) {
			if (!best || (parseFloat(opts[i].score) || 0) < (parseFloat(best.score) || 0)) best = opts[i];
		}
		return best;
	}

	function evaluateNumberCondition(optionsArray, valueToCheck) {
		var val = parseFloat(valueToCheck);
		if (isNaN(val)) return '';

		var defaultOptionId = '';

		for (var i = 0; i < optionsArray.length; i++) {
			var opt = optionsArray[i];

			if (opt.operator) {
				switch (opt.operator) {
					case 'gte':     if (val >= opt.minValue) return opt.sys_id; break;
					case 'lte':     if (val <= opt.maxValue) return opt.sys_id; break;
					case 'gt':      if (val >  opt.minValue) return opt.sys_id; break;
					case 'lt':      if (val <  opt.maxValue) return opt.sys_id; break;
					case 'between': if (val >= opt.minValue && val <= opt.maxValue) return opt.sys_id; break;
				}
				continue;
			}

			var cleanLabel = (opt.label || '').toLowerCase().split('(score')[0].replace(/,/g, '').trim();

			if (/\bdefault\b/.test(cleanLabel) && !defaultOptionId) {
				defaultOptionId = opt.sys_id;
				continue;
			}

			var rangeMatch = cleanLabel.match(/([\d.]+)\s*-\s*([\d.]+)/);
			if (rangeMatch) {
				var min = parseFloat(rangeMatch[1]), max = parseFloat(rangeMatch[2]);
				if (val >= min && val <= max) return opt.sys_id;
				continue;
			}

			var singleMatch = cleanLabel.match(/([\d.]+)/);
			if (singleMatch) {
				var numVal = parseFloat(singleMatch[1]);

				if (cleanLabel.indexOf('>=') !== -1 && val >= numVal) return opt.sys_id;
				else if (cleanLabel.indexOf('<=') !== -1 && val <= numVal) return opt.sys_id;
				else if (cleanLabel.indexOf('=') === -1 && (cleanLabel.indexOf('>') !== -1 || cleanLabel.indexOf('above') !== -1 || cleanLabel.indexOf('greater') !== -1 || cleanLabel.indexOf('more') !== -1) && val > numVal) return opt.sys_id;
				else if (cleanLabel.indexOf('=') === -1 && (cleanLabel.indexOf('<') !== -1 || cleanLabel.indexOf('below') !== -1 || cleanLabel.indexOf('less') !== -1) && val < numVal) return opt.sys_id;
				else if (val === numVal) {
					return opt.sys_id;
				}
			}
		}

		return defaultOptionId;
	}

	// Rating / scoring
	function getExternalRating(ratingStr, p2Score) {
		ratingStr = (ratingStr || '').toUpperCase().trim();
		if (ratingStr) {
			for (var grade in CONFIG.RATING_BANDS) {
				var bands = CONFIG.RATING_BANDS[grade];
				for (var k = 0; k < bands.length; k++) {
					if (ratingStr.indexOf(bands[k]) > -1) return grade;
				}
			}
		}
		var p2Pct = p2Score * 100;
		if (p2Pct >= 61) return 'A';
		if (p2Pct >= 31) return 'B';
		return 'C';
	}

	function externalRatingInfo(ratingStr, p2Score) {
		var raw = (ratingStr || '').toUpperCase().trim();
		var grade = getExternalRating(raw, p2Score);
		var fromDoc = false;
		if (raw) {
			for (var g in CONFIG.RATING_BANDS) {
				for (var k = 0; k < CONFIG.RATING_BANDS[g].length; k++) {
					if (raw.indexOf(CONFIG.RATING_BANDS[g][k]) > -1) fromDoc = true;
				}
			}
		}
		return {
			grade: grade,
			raw: ratingStr || '',
			source: fromDoc ? 'Document rating: ' + ratingStr
			: 'Composite index band (>= 61% A, >= 31% B, else C)'
		};
	}

	function getP3(extR, intR) {
		return (CONFIG.P3_GRID[extR] && CONFIG.P3_GRID[extR][intR] !== undefined) ? CONFIG.P3_GRID[extR][intR] : 0.00;
	}

	function rateFromBuckets(safeL, midM, critN, toxO, recCount) {
		var grand = safeL + midM + critN + toxO;
		if (grand === 0 || recCount === 0) return { rating: 'A', pctL: 0, pctCT: 0 };

		var pctL  = (safeL / grand) * 100;
		var pctCT = ((critN + toxO) / grand) * 100;

		var rating;
		if (pctL >= 80 && pctCT <= 10) rating = 'A';
		else if (pctL >= 60 && pctCT <= 20) rating = 'B';
		else rating = 'C';

		return { rating: rating, pctL: pctL, pctCT: pctCT };
	}

	function getInternalRating(panValue) {
		var recCount = 0, months = 0;
		var b = { b0_30: 0, b31_45: 0, b46_60: 0, b61_75: 0, b76_90: 0, b91_120: 0, bGt120: 0 };
		function n(gr, f) { return parseFloat(gr.getValue(f)) || 0; }

		var cGr = new GlideRecord(CONFIG.TABLES.CUSTOMER);
		cGr.addQuery('pan', panValue);
		cGr.query();

		while (cGr.next()) {
			var custSysId = cGr.getUniqueValue();
			var oGr = new GlideRecord(CONFIG.TABLES.OUTSTANDING);
			oGr.addQuery('customer', custSysId);
			oGr.orderByDesc('sys_created_on');
			oGr.setLimit(6);
			oGr.query();

			var siteRecs = 0;
			while (oGr.next()) {
				recCount++; siteRecs++;
				b.b0_30   += n(oGr, 'bucket_0_30_days');
				b.b31_45  += n(oGr, 'bucket_31_45_days');
				b.b46_60  += n(oGr, 'bucket_46_60_days');
				b.b61_75  += n(oGr, 'bucket_61_75_days');
				b.b76_90  += n(oGr, 'bucket_76_90_days');
				b.b91_120 += n(oGr, 'bucket_91_120_days');
				b.bGt120  += n(oGr, 'bucket_121_180_days') + n(oGr, 'bucket_gt120_days');
			}
			if (siteRecs > months) months = siteRecs;
		}

		var safeL = b.b0_30 + b.b31_45 + b.b46_60, midM = b.b61_75, critN = b.b76_90, toxO = b.b91_120 + b.bGt120;
		var r = rateFromBuckets(safeL, midM, critN, toxO, recCount);
		r.buckets = b;
		r.months = months;
		return r;
	}

	// Site inputs. A value counts only when it is a number > 0 (empty / 0 falls through to the next source).
	function readPositive(gr, field) {
		if (!field || !gr.isValidField(field)) return null;
		var v = gr.getValue(field);
		if (isBlankVal(v)) return null;
		var n = parseFloat(v);
		return (!isNaN(n) && n > 0) ? n : null;
	}

	function readInputs(gr, map) {
		return {
			potential:   readPositive(gr, map.potential),
			currentQty:  readPositive(gr, map.currentQty),
			expectedQty: readPositive(gr, map.expectedQty),
			rate:        readPositive(gr, map.rate),
			tenor:       readPositive(gr, map.tenor)
		};
	}

	function zeroIfNull(v) { return v === null || v === undefined ? 0 : v; }

	// Raw customer-master values (0 when empty). Used for every site that is NOT part of the request.
	function readMasterInputs(custGr) {
		var m = readInputs(custGr, CONFIG.MASTER_FIELDS);
		return {
			potential:   zeroIfNull(m.potential),
			currentQty:  zeroIfNull(m.currentQty),
			expectedQty: zeroIfNull(m.expectedQty),
			rate:        zeroIfNull(m.rate),
			tenor:       zeroIfNull(m.tenor)
		};
	}

	// Step 2 prefill: customer form first, customer master as backup (field by field), otherwise 0
	function fetchSiteInputs(custGr) {
		var master = readInputs(custGr, CONFIG.MASTER_FIELDS);
		var form = null;

		var cfGr = new GlideRecord(CONFIG.TABLES.CUSTOMER_FORM);
		var cfQc = cfGr.addQuery('customer', custGr.getUniqueValue());
		cfQc.addOrCondition('customer_code', custGr.getUniqueValue());
		cfGr.orderByDesc('sys_created_on');
		cfGr.setLimit(1);
		cfGr.query();
		if (cfGr.next()) form = readInputs(cfGr, CONFIG.FORM_FIELDS);

		function pick(key) {
			if (form && form[key] !== null) return form[key];
			if (master[key] !== null) return master[key];
			return 0;
		}

		var pot    = pick('potential');
		var curQty = pick('currentQty');
		var expQty = pick('expectedQty');
		var tenor  = pick('tenor');

		return {
			totalPotential: pot,
			orderRate:      pick('rate'),
			currentSob:     curQty,
			expectedSob:    expQty,
			currentSobPct:  pot > 0 ? round2(curQty / pot * 100) : 0,
			expectedSobPct: pot > 0 ? round2(expQty / pot * 100) : 0,
			creditTenor:    tenor > 0 ? parseInt(tenor, 10) : CONFIG.DEFAULT_CREDIT_TENOR,
			justification:  ''
		};
	}

	// Composite index (P2)
	// Fallback grouping (only used when no site rows are supplied): master values for every site under the PAN
	function getAllSitesGroupedBySegment(panValue) {
		var grouped = {};
		var gr = new GlideRecord(CONFIG.TABLES.CUSTOMER);
		gr.addQuery('pan', panValue);
		gr.addQuery('cg1', 'N01');
		gr.query();

		while (gr.next()) {
			var segDisplay = gr.getDisplayValue('segment') || 'Unknown';
			var key = segKey(segDisplay) || segDisplay;
			var m = readMasterInputs(gr);

			if (!grouped[key]) grouped[key] = [];
			grouped[key].push({
				code: gr.getValue('customer_code_sap'),
				potential: m.potential,
				expectedSob: m.expectedQty,
				currentSob: m.currentQty,
				currentSobPct: m.potential > 0 ? round2(m.currentQty / m.potential * 100) : 0,
				expectedSobPct: m.potential > 0 ? round2(m.expectedQty / m.potential * 100) : 0,
				orderRate: m.rate
			});
		}
		return grouped;
	}

	// Average order rate of a segment's sites (see CONFIG.AVG_RATE_MODE)
	function segmentAverageRate(sites) {
		var rated = sites.filter(function(s) { return (parseFloat(s.orderRate) || 0) > 0; });
		if (!rated.length) return 0;
		if (CONFIG.AVG_RATE_MODE === 'potential') {
			var pot = 0, potRate = 0;
			rated.forEach(function(s) { pot += s.potential; potRate += s.potential * s.orderRate; });
			if (pot > 0) return potRate / pot;
		}
		return rated.reduce(function(t, s) { return t + s.orderRate; }, 0) / rated.length;
	}

	// One segment's composite index. The PAN-wide parameters are the same for every segment; Current SOB %
	// and Potential (MPQ) are scored from ALL sites of this segment under the PAN
	// (request sites: Step 2 values, other sites: customer master values).
	// Financial weight = MPQ x average order rate (used to weight the segment indices into the PAN P2).
	function computeSegmentComposite(sites, groupedParameters, segment) {
		var potentialSum = 0, currentSobAmtSum = 0, expectedSum = 0;

		sites.forEach(function(s) {
			potentialSum += s.potential;
			expectedSum  += parseFloat(s.expectedSob) || 0;
			currentSobAmtSum += (s.currentSob !== undefined && s.currentSob !== null)
				? (parseFloat(s.currentSob) || 0)
			: s.potential * ((s.currentSobPct || 0) / 100);
		});

		var segCurrentSobPct = potentialSum > 0 ? (currentSobAmtSum / potentialSum * 100) : 0;
		var avgRate = segmentAverageRate(sites);
		var weightSum = expectedSum * avgRate;

		var rawScore = 0, totalMax = 0;
		var paramTrace = [];

		for (var cat in groupedParameters) {
			var arr = groupedParameters[cat];
			for (var i = 0; i < arr.length; i++) {
				var p = arr[i];
				if (!isParamRelevant(p, segment)) continue;

				var pNameLower = (p.name || '').toLowerCase();
				var effectiveSelId;
				var source;
				var kind = '', kindValue = null;

				if (isShareOrSobParam(pNameLower)) {
					effectiveSelId = evaluateNumberCondition(p.options, segCurrentSobPct);
					source = 'segment-aggregated Current SOB% (' + segCurrentSobPct.toFixed(2) + '%)';
					kind = 'sob'; kindValue = round2(segCurrentSobPct);
				} else if (isPotentialParam(pNameLower)) {
					effectiveSelId = evaluateNumberCondition(p.options, expectedSum);
					source = 'segment-aggregated Potential (' + potentialSum.toFixed(2) + ')';
					kind = 'potential'; kindValue = round2(expectedSum);
				} else {
					effectiveSelId = p.selectedValue;
					source = 'PAN-wide selection (Step 3)';
				}

				if (!effectiveSelId) {
					var lowOpt = getLowestOption(p);
					if (!lowOpt) continue;
					effectiveSelId = lowOpt.sys_id;
					source += ' -> nothing selected / matched, lowest score applied';
				}
				var opt = null;
				for (var j = 0; j < p.options.length; j++) {
					if (p.options[j].sys_id === effectiveSelId) { opt = p.options[j]; break; }
				}
				if (opt) {
					rawScore += (opt.score * opt.weight);
					totalMax += (10 * opt.weight);
					paramTrace.push({
						name: p.name, optionId: opt.sys_id, label: opt.label,
						score: parseFloat(opt.score) || 0, weight: parseFloat(opt.weight) || 0, source: source,
						kind: kind, value: kindValue,
						panWide: isPanWideParam(p) && !isShareOrSobParam(pNameLower) && !isPotentialParam(pNameLower)
					});
				}
			}
		}

		var segIndex = totalMax > 0 ? (rawScore / totalMax) : 0;

		return {
			segment: segment,
			index: segIndex,
			potentialSum: potentialSum,
			expectedPotentialSum: expectedSum,
			currentSobPct: segCurrentSobPct,
			avgRate: avgRate,
			weight: weightSum,
			siteCount: sites.length,
			paramTrace: paramTrace
		};
	}

	function computePanLevelCompositeIndex(panValue, groupedParameters, siteRows) {
		var grouped;
		if (siteRows) {
			grouped = {};
			siteRows.forEach(function(r) {
				if (!r.segKey) return;
				if (!grouped[r.segKey]) grouped[r.segKey] = [];
				grouped[r.segKey].push({
					code: r.code, potential: r.potential, currentSob: r.currentSob, currentSobPct: r.currentSobPct,
					expectedSob: r.expectedSob,
					expectedSobPct: r.expectedSobPct, orderRate: r.orderRate
				});
			});
		} else {
			grouped = getAllSitesGroupedBySegment(panValue);
		}
		var segResults = [];
		var weightedNum = 0, weightedDen = 0;

		// Only segments that have at least one site are scored / shown
		SEGMENTS.forEach(function(seg) {
			var sites = grouped[seg];
			if (!sites || sites.length === 0) return;
			var r = computeSegmentComposite(sites, groupedParameters, seg);
			segResults.push(r);
			weightedNum += r.index * r.weight;
			weightedDen += r.weight;
		});

		var usedFallback = false;
		var panIndex;
		if (weightedDen > 0) {
			panIndex = weightedNum / weightedDen;
		} else if (segResults.length > 0) {
			usedFallback = true;
			panIndex = segResults.reduce(function(sum, r) { return sum + r.index; }, 0) / segResults.length;
		} else {
			panIndex = 0;
		}

		return { panIndex: panIndex, segments: segResults, usedFallback: usedFallback };
	}

	// Stores the scored option of every segment parameter (Current SOB %, Potential, ...) for the segments
	// other than the requested one, using the PAN-level totals, so each segment's P2 can be rechecked later
	function storeOtherSegmentParameters(requestId, segments, activeKey) {
		segments.forEach(function(seg) {
			if (seg.segment === activeKey) return;
			seg.paramTrace.forEach(function(t) {
				if (t.panWide) return;
				var gr = new GlideRecord(CONFIG.TABLES.REQ_PARAMS);
				gr.initialize();
				gr.setValue('request', requestId);
				gr.setValue('risk_parameter', t.optionId);
				if (gr.isValidField('segment')) gr.setValue('segment', seg.segment);
				gr.insert();
			});
		});
	}

	// Batch metrics
	function computeBatchMetrics(sites, intR, isListed, panP1IfListed, externalRatingInput, uniformP2, panMaclAll) {
		var batchSafeLimit = 0, aggregatedP1 = 0, totalP3 = 0;
		var perSite = [];

		sites.forEach(function(s) {
			var p1 = parseFloat(s.p1) || 0;
			var p2 = uniformP2;

			var extR = getExternalRating(externalRatingInput, p2);
			var p3 = getP3(extR, intR);
			var safe = parseFloat((p1 * p2 * p3).toFixed(4));

			batchSafeLimit += safe;
			aggregatedP1 += p1;
			totalP3 += p3;

			perSite.push({ p1: p1, p2: p2, p3: p3, safe: safe, extR: extR });
		});

		var avgP3 = sites.length > 0 ? parseFloat((totalP3 / sites.length).toFixed(4)) : 0;

		if (sites.length === 0) avgP3 = getP3(getExternalRating(externalRatingInput, uniformP2), intR);

		var maclBase = isListed ? panP1IfListed
		: (panMaclAll !== undefined && panMaclAll !== null ? panMaclAll : aggregatedP1);
		var finalSafe = parseFloat((maclBase * uniformP2 * avgP3).toFixed(4));

		return {
			intR: intR,
			batchP2Avg: uniformP2,
			avgP3: avgP3,
			finalSafe: finalSafe,
			aggregatedP1: maclBase,
			selectedSitesSafe: parseFloat(batchSafeLimit.toFixed(4)),
			perSite: perSite
		};
	}

	// Step 1 helpers
	function isUserAuthorizedForSite(custGr, segValue, currentUser) {
		if (gs.hasRole('x_birl3_clm.admin')) return true;

		var mxGr = new GlideRecord(CONFIG.TABLES.MATRIX);
		var qc = mxGr.addQuery('role_name', 'CONTAINS', 'TSH');
		qc.addOrCondition('role_name', 'CONTAINS', 'TSM');
		mxGr.addQuery('customer_type', 'non_trade');
		mxGr.addQuery('segment', segValue);
		var zq = mxGr.addQuery('zone', custGr.getValue('zone'));
		zq.addOrCondition('zone', 'ISEMPTY');
		var rq = mxGr.addQuery('region', custGr.getValue('region'));
		rq.addOrCondition('region', 'ISEMPTY');
		var dq = mxGr.addQuery('depot', custGr.getValue('depot'));
		dq.addOrCondition('depot', 'ISEMPTY');
		mxGr.setLimit(1);
		mxGr.query();

		return mxGr.next() && mxGr.getValue('approver_user') == currentUser;
	}

	function fetchOutstandingBuckets(custSysId) {
		var totalOs = 0;
		var buckets = [];
		var firstRun = true;

		var outGr = new GlideRecord(CONFIG.TABLES.OUTSTANDING);
		outGr.addQuery('customer', custSysId);
		outGr.orderByDesc('snapshot_month');
		outGr.setLimit(6);
		outGr.query();

		while (outGr.next()) {
			var b03  = parseFloat(outGr.getValue('bucket_0_30_days'))   || 0;
			var b47  = parseFloat(outGr.getValue('bucket_31_45_days'))  || 0;
			var b821 = parseFloat(outGr.getValue('bucket_46_60_days'))  || 0;
			var b22  = parseFloat(outGr.getValue('bucket_61_75_days'))  || 0;
			var b31  = parseFloat(outGr.getValue('bucket_76_90_days'))  || 0;
			var bgt  = (parseFloat(outGr.getValue('bucket_91_120_days'))  || 0) + (parseFloat(outGr.getValue('bucket_121_180_days')) || 0) + (parseFloat(outGr.getValue('bucket_gt120_days')) || 0);

			var rawVal = outGr.getValue('total_outstanding') || outGr.getValue('u_net_balance');
			var rowTotalOs = (rawVal !== null && rawVal !== '') ? Math.abs(parseFloat(rawVal)) : Math.abs(b03 + b47 + b821 + b22 + b31 + bgt);

			buckets.push({
				month: (outGr.getValue('snapshot_month') || '').split(' ')[0],
				b0_3: b03, b4_7: b47, b8_21: b821, b22_30: b22, b31_45: b31,
				b46_60: 0, b61_75: 0, b76_90: 0, b_gt90: bgt,
				total_os: rowTotalOs
			});

			if (firstRun) {
				totalOs = rowTotalOs;
				firstRun = false;
			}
		}
		return { totalOs: totalOs, buckets: buckets };
	}

	function getActiveRequestType(custSysId) {
		var activeReqGr = new GlideRecord(CONFIG.TABLES.SITE_REQUEST);
		activeReqGr.addQuery('customer_site_code', custSysId);
		var stateQc = activeReqGr.addQuery('approval', 'NOT IN', 'approved,rejected');
		//stateQc.addOrCondition('state', 'NOT IN', '3,7');
		activeReqGr.setLimit(1);
		activeReqGr.query();
		if (activeReqGr.hasNext()) return 'CL';

		var swapReqGr = new GlideRecord(CONFIG.TABLES.LIMIT_SWAP);
		var swapQc = swapReqGr.addQuery('donee', custSysId);
		swapQc.addOrCondition('donor', custSysId);
		var swapStateQc = swapReqGr.addQuery('approval', 'NOT IN', 'approved,rejected');
		swapStateQc.addOrCondition('state', 'NOT IN', '3,7');
		swapReqGr.setLimit(1);
		swapReqGr.query();
		return swapReqGr.hasNext() ? 'Swap' : '';
	}

	// Action handlers
	function handleFetchPanSuggestions() {
		var searchString = input.panNumber ? input.panNumber.toUpperCase().trim() : '';
		data.panSuggestions = [];
		if (searchString.length < 3) return;

		var ga = new GlideRecord(CONFIG.TABLES.CUSTOMER);
		var qc = ga.addQuery('pan', 'STARTSWITH', searchString);
		qc.addOrCondition('customer_name', 'CONTAINS', searchString);
		ga.addNotNullQuery('pan');
		ga.orderBy('pan');
		ga.setLimit(CONFIG.PAN_SUGGESTION_SCAN);
		ga.query();

		var addedPans = {};
		while (ga.next() && data.panSuggestions.length < CONFIG.MAX_PAN_SUGGESTIONS) {
			var panVal = ga.getValue('pan');
			var nameVal = ga.getValue('customer_name');
			if (panVal && !addedPans[panVal]) {
				data.panSuggestions.push({ pan: panVal, name: nameVal });
				addedPans[panVal] = true;
			}
		}
	}

	function handleFetchCustomers() {
		var custSearchString = input.panNumber ? input.panNumber.toUpperCase() : '';
		data.customers = [];
		data.panTotals = { limit: 0, bg: 0, activeBg: 0, netExposure: 0, outstanding: 0 };

		var gr = new GlideRecord(CONFIG.TABLES.CUSTOMER);
		gr.addQuery('pan', custSearchString);
		gr.addQuery('cg1', 'N01');
		gr.orderBy('customer_code_sap');
		gr.query();

		var currentUser = gs.getUserID();

		while (gr.next()) {
			var custSysId = gr.getUniqueValue();
			var custCode  = gr.getValue('customer_code_sap');

			var firstOrder = gr.getValue('first_order_date');
			var ageInYears = 0;
			if (firstOrder) {
				var gdtNow = new GlideDateTime();
				var gdtFirst = new GlideDateTime(firstOrder);
				ageInYears = gdtNow.getYearLocalTime() - gdtFirst.getYearLocalTime();
			}
			if (ageInYears < 0) ageInYears = 0;

			var segDisplay = gr.getDisplayValue('segment') || 'Unknown';
			var segValue   = gr.getValue('segment');

			var zoneStr   = formatLocation(gr.getValue('zone'),   gr.getValue('zone_name'));
			var regionStr = formatLocation(gr.getValue('region'), gr.getValue('region_name'));
			var depotStr  = formatLocation(gr.getValue('depot'),  gr.getValue('depot_name'));

			var isAuthorized = isUserAuthorizedForSite(gr, segValue, currentUser);
			var bucketData   = fetchOutstandingBuckets(custSysId);
			var activeType   = getActiveRequestType(custSysId);
			var siteInputs   = fetchSiteInputs(gr);        // form first -> master -> 0 (Step 2 prefill)
			var masterInputs = readMasterInputs(gr);       // raw master values (used when the site is not in the request)

			var derivedNod = calculateSiteNOD(custSysId, custCode, segDisplay, bucketData.totalOs);

			data.panTotals.outstanding += bucketData.totalOs;

			data.customers.push({
				sys_id:           custSysId,
				code:             custCode,
				salesOrg:         gr.getValue('salesorg'),
				name:             gr.getValue('customer_name'),
				city:             gr.getValue('city_desc') || 'N/A',
				limit:            0,
				bg:               0,
				activeBg:         0,
				bgExpiry:         gr.getValue('bg_expiry_date') || 'No Expiry Data',
				bgExpiryRaw:      gr.getValue('bg_expiry_date'),
				outstanding:      bucketData.totalOs,
				segmentDisplay:   segDisplay,
				segmentValue:     segValue,
				zone:             zoneStr,
				region:           regionStr,
				depot:            depotStr,
				age:              ageInYears,
				buckets:          bucketData.buckets,
				expanded:         false,
				selected:         false,
				hasActiveRequest: !!activeType,
				activeRequestType: activeType,
				missingTSH:       !isAuthorized,

				nod:              derivedNod,

				// Step 2 prefill (editable by the user)
				totalPotential: siteInputs.totalPotential,
				orderRate:      siteInputs.orderRate,
				currentSob:     siteInputs.currentSob,
				expectedSob:    siteInputs.expectedSob,
				currentSobPct:  siteInputs.currentSobPct,
				expectedSobPct: siteInputs.expectedSobPct,
				creditTenor:    siteInputs.creditTenor,
				justification:  siteInputs.justification,

				// Customer master values (segment totals, MACL and composite for sites NOT in the request)
				masterPotential:   masterInputs.potential,
				masterCurrentSob:  masterInputs.currentQty,
				masterExpectedSob: masterInputs.expectedQty,
				masterRate:        masterInputs.rate,
				masterTenor:       masterInputs.tenor
			});
		}
		data.panTotals.netExposure = data.panTotals.limit - data.panTotals.activeBg;
	}

	function handleFetchSapData() {
		var custCode = input.custCode;
		var salesOrg = input.salesOrg;
		var bgExpiryRaw = input.bgExpiryRaw;

		var liveCreditLimit = 0, liveBg = 0, apiFirstOrderDate = '';

		try {
			var obj = new x_birl3_clm.CLM_NEW_WSDL1();
			var response = obj.getCreditDetails(custCode, salesOrg);

			if (response) {
				var json = JSON.parse(response);
				liveCreditLimit = parseFloat(json.creditLimit) || 0;
				liveBg          = Math.abs(parseFloat(json.actBg)) || 0;

				if (json.firstOrderDate && json.firstOrderDate != "0000-00-00") apiFirstOrderDate = json.firstOrderDate;
				if (json.expryDate && json.expryDate != "0000-00-00") bgExpiryRaw = json.expryDate;
			}
		} catch (e) {
			gs.error("CLM API Error for " + custCode + ": " + e.message);
		}

		var activeBgVal = 0;
		if (liveBg > 0 && bgExpiryRaw && bgExpiryRaw !== "0000-00-00") {
			var expiryDatePart = bgExpiryRaw.toString().split(' ')[0];
			var expiryDateTime = new GlideDateTime(expiryDatePart + ' 23:59:59');
			var nowDateTime = new GlideDateTime();
			if (expiryDateTime.compareTo(nowDateTime) >= 0) {
				activeBgVal = liveBg;
			}
		}

		var ageInYears = 0;
		if (apiFirstOrderDate && apiFirstOrderDate !== "0000-00-00") {
			var dateStr = apiFirstOrderDate.toString().trim();
			if (dateStr.indexOf(' ') === -1) {
				dateStr += ' 00:00:00';
			}
			var gdtNow = new GlideDateTime();
			var gdtFirst = new GlideDateTime(dateStr);
			var dur = GlideDateTime.subtract(gdtFirst, gdtNow);
			ageInYears = Math.floor(dur.getDayPart() / 365);
			if (ageInYears < 0) ageInYears = 0;
		}

		var tableSnap = new GlideRecord(CONFIG.TABLES.OUTSTANDING);
		tableSnap.addEncodedQuery('customer.customer_code_sap=' + custCode + '^ORcustomer=' + custCode);
		tableSnap.orderByDesc('snapshot_month');
		tableSnap.setLimit(1);
		tableSnap.query();
		var tableOs = 0;
		if (tableSnap.next()) {
			tableOs = Math.abs(parseFloat(tableSnap.getValue('total_outstanding') || tableSnap.getValue('u_net_balance'))) || 0;
		}
		var derivedNod = calculateSiteNOD('', custCode, input.segment || 'Cement', tableOs);

		data.sapData = {
			limit:       liveCreditLimit,
			bg:          liveBg,
			activeBg:    activeBgVal,
			outstanding: tableOs,
			nod:         derivedNod,
			age:         ageInYears,
			bgExpiry:    bgExpiryRaw
		};
	}

	function handleFetchParameters() {
		loadMatrixParameters();
		data.thresholds = getThresholds();
	}

	function handleCreateRecord() {
		if (input.fileData) {
			var approxBytes = Math.ceil((input.fileData.length * 3) / 4);
			if (approxBytes > CONFIG.MAX_UPLOAD_BYTES) {
				data.serverError = 'Uploaded document exceeds the 5MB limit. Please upload a smaller file.';
				return;
			}
		}

		try {
			var targetOcrTable = '';
			if (input.documentType === 'CRIF') {
				targetOcrTable = CONFIG.TABLES.OCR_CRIF;
			} else if (input.documentType === 'Balance Sheet') {
				targetOcrTable = CONFIG.TABLES.OCR_BS;
			} else if (input.documentType === 'Corpository') {
				targetOcrTable = CONFIG.TABLES.OCR_CORP;
			} else {
				targetOcrTable = CONFIG.TABLES.OCR_CRIF;
			}

			var ocr = new GlideRecord(targetOcrTable);
			if (!ocr.isValid()) {
				data.serverError = "Table Error: The backend table '" + targetOcrTable + "' does not exist.";
				return;
			}

			ocr.initialize();
			var sysId = ocr.insert();

			if (!sysId) {
				data.serverError = 'Failed to create tracking session record.';
				return;
			}

			if (input.fileData && input.fileName && input.fileType) {
				safeAttach(ocr, input.fileName, input.fileType, input.fileData);
			}

			data.sysId = sysId;
			data.targetTable = targetOcrTable;

		} catch (e) {
			data.serverError = 'Session creation error: ' + e.message;
			return;
		}

		loadMatrixParameters();
		data.thresholds = getThresholds();
	}

	function handlePoll() {
		if (!input.sysId) {
			data.pollError = 'Context tracking reference session ID is missing.';
			return;
		}

		var targetTable = input.targetTable;
		var rec = new GlideRecord(targetTable);
		if (!rec.get(input.sysId)) {
			data.pollError = 'Tracking entity not found.';
			return;
		}

		var checkFields = ['name_of_company', 'net_revenue', 'rating', 'risk_index', 'ap_days', 'u_ap_days'];
		var hasDataExtracted = checkFields.some(function(f) { return getSafeValue(rec, [f]) !== ''; });

		if (!hasDataExtracted) {
			data.ocrStatus = 'processing';
			return;
		}

		data.ocrStatus = 'success';
		data.result = {
			court_cases:    getSafeValue(rec, ['court_cases']),
			rating:         getSafeValue(rec, ['rating']),
			risk_index:     getSafeValue(rec, ['risk_index']),
			ap_days:        getSafeValue(rec, ['ap_days', 'u_ap_days']),
			ar_days:        getSafeValue(rec, ['ar_days', 'u_ar_days']),
			debt_equity:    getSafeValue(rec, ['debt_equity']),
			ebitda:         getSafeValue(rec, ['ebitda', 'u_ebitda_percent']),
			gross_profit:   getSafeValue(rec, ['gross_profit', 'u_gross_profit_percent']),
			int_coverage:   getSafeValue(rec, ['int_coverage', 'u_interest_coverage']),
			inventory_days: getSafeValue(rec, ['inventory_days', 'u_inventory_days']),
			net_revenue:    getSafeValue(rec, ['net_revenue', 'total_revenue', 'u_sales']),
			net_wcc_days:   getSafeValue(rec, ['net_wcc_days', 'u_net_wcc_days']),
			sales_growth:   getSafeValue(rec, ['sales_growth', 'u_sales_growth_pct']),
			net_worth:      getSafeValue(rec, ['networth']),
			loans_advances: getSafeValue(rec, ['loans_advances'])
		};
	}

	function handlePreviewReview() {
		var isListed = (input.panLevel.companyType === 'Listed');
		var panP1 = 0;
		if (isListed) {
			var nw = parseFloat(input.panLevel.netWorth) || 0;
			var la = parseFloat(input.panLevel.loansAdvances) || 0;
			panP1 = Math.max(0, 0.05 * (nw - 0.5 * la));
		}

		var activeSegment = input.selectedCustomers.length ? input.selectedCustomers[0].segmentDisplay : null;

		for (var vi = 0; vi < input.selectedCustomers.length; vi++) {
			var sobErr = validateSob(input.selectedCustomers[vi]);
			if (sobErr) { data.serverError = sobErr; return; }
		}

		var siteRows = buildPanSiteRows(isListed);
		var panMaclAll = sumBy(siteRows, 'macl');

		var compositeResult = computePanLevelCompositeIndex(input.panNumber, input.groupedParameters, siteRows);
		var batchP2 = compositeResult.panIndex;

		var sites = input.selectedCustomers.map(function(cust) {
			var sob = getSobFigures(cust);
			var p1;
			if (isListed) {
				p1 = panP1;
			} else {
				var tenor = (cust.creditTenor !== null && cust.creditTenor !== undefined) ? parseInt(cust.creditTenor, 10) : CONFIG.DEFAULT_CREDIT_TENOR;
				p1 = sob.expQty * (parseFloat(cust.orderRate) || 0) * (tenor / 30);
			}
			if (isNaN(p1) || p1 < 0) p1 = 0;

			return {
				code: cust.code, name: cust.name, segment: cust.segmentDisplay,
				limit: cust.limit, outstanding: cust.outstanding, activeBg: cust.activeBg,
				totalPotential: sob.pot,
				currentSob: sob.curQty,
				expectedSob: sob.expQty,
				currentSobPct: sob.curPct,
				expectedSobPct: sob.expPct,
				orderRate: parseFloat(cust.orderRate) || 0,
				creditTenor: (cust.creditTenor !== null && cust.creditTenor !== undefined) ? cust.creditTenor : CONFIG.DEFAULT_CREDIT_TENOR,
				nod: cust.nod || 0,
				expectedPotentialAmt: cust.expectedPotentialAmt,
				p1: p1, desiredLimit: cust.desiredLimit
			};
		});

		var ratingInfo = getInternalRating(input.panNumber);
		var batchMetrics = computeBatchMetrics(sites, ratingInfo.rating, isListed, panP1, input.externalRating || '', batchP2, panMaclAll);

		var totalDesired = sites.reduce(function(sum, s) { return sum + (parseFloat(s.desiredLimit) || 0); }, 0);
		var totalCurrentLimitSelected = sites.reduce(function(sum, s) { return sum + (parseFloat(s.limit) || 0); }, 0);
		var effectivePanTotal = parseFloat(input.panTotals.limit) || 0;
		var projectedPanLimit = effectivePanTotal - totalCurrentLimitSelected + totalDesired;

		var segmentLimitTotal = 0, segmentBgTotal = 0;
		(input.customers || []).forEach(function(cst) {
			if (cst.segmentDisplay === activeSegment) {
				var picked = input.selectedCustomers.find(function(sc) { return sc.code === cst.code; });
				segmentLimitTotal += picked ? parseFloat(picked.desiredLimit || 0) : parseFloat(cst.limit || 0);
				segmentBgTotal += parseFloat(cst.activeBg || 0);
			}
		});
		var segmentNetExposure = segmentLimitTotal - segmentBgTotal;
		var panAggregateNetExposure = (parseFloat(input.panTotals.limit) || 0) - (parseFloat(input.panTotals.activeBg) || 0) + segmentNetExposure;

		var thresholds = getThresholds();
		var toolWorkingThreshold = getToolWorkingThreshold(activeSegment, thresholds);
		var triggerToolWorking = (segmentNetExposure >= toolWorkingThreshold);

		data.reviewSites = sites.map(function(s, i) {
			var m = batchMetrics.perSite[i];
			return {
				code: s.code, customerName: s.name, segment: s.segment, limit: s.limit, outstanding: s.outstanding,
				nod: s.nod,
				p1: m.p1, p2: m.p2, p3: m.p3, safeLimit: m.safe, desiredLimit: s.desiredLimit
			};
		});

		var segView = buildSegmentRows(siteRows);
		data.reviewSegments = segView.rows;
		data.reviewSegmentTotal = segView.total;

		data.reviewMacl = {
			isListed: isListed,
			rows: siteRows,
			totals: {
				macl: panMaclAll,
				currentCl: sumBy(siteRows, 'currentCl'),
				updatedCl: sumBy(siteRows, 'updatedCl')
			},
			aggregated: batchMetrics.aggregatedP1,
			listed: isListed ? {
				netWorth: parseFloat(input.panLevel.netWorth) || 0,
				loansAdvances: parseFloat(input.panLevel.loansAdvances) || 0,
				panMacl: panP1
			} : null
		};

		data.reviewComposite = {
			panIndex: batchP2,
			usedFallback: compositeResult.usedFallback,
			documentType: input.documentType || '',
			isManualMode: !!input.isManualMode,
			segments: compositeResult.segments
		};

		var ext = externalRatingInfo(input.externalRating || '', batchP2);
		var bk = ratingInfo.buckets || {};
		var div = Math.max(1, ratingInfo.months || 0);
		var bucketRows = [
			{ key: 'b0_30',   label: '0-30',    group: 'safe' },
			{ key: 'b31_45',  label: '31-45',   group: 'safe' },
			{ key: 'b46_60',  label: '46-60',   group: 'safe' },
			{ key: 'b61_75',  label: '61-75',   group: 'warn' },
			{ key: 'b76_90',  label: '76-90',   group: 'warn' },
			{ key: 'b91_120', label: '91-120',  group: 'risk' },
			{ key: 'bGt120',  label: '>120',    group: 'risk' }
		];
		var avgTotal = 0;
		bucketRows.forEach(function(r) { r.avg = (bk[r.key] || 0) / div; avgTotal += r.avg; });
		bucketRows.forEach(function(r) { r.pct = avgTotal > 0 ? (r.avg / avgTotal) * 100 : 0; });

		data.reviewCredit = {
			months: ratingInfo.months || 0,
			buckets: bucketRows,
			avgTotal: avgTotal,
			internal: { grade: ratingInfo.rating, pctSafe: ratingInfo.pctL, pctCritical: ratingInfo.pctCT },
			external: ext,
			p3: batchMetrics.avgP3
		};

		var updatedPanLimit = segView.total.updatedLimit;

		data.reviewSummary = {
			panP1: batchMetrics.aggregatedP1,
			panP2: batchMetrics.batchP2Avg,
			panP3: batchMetrics.avgP3,
			safeLimit: batchMetrics.finalSafe,
			toolWorkingThreshold: toolWorkingThreshold,
			activeSegment: activeSegment,
			updatedPanLimit: updatedPanLimit,
			withinSafeLimit: updatedPanLimit <= batchMetrics.finalSafe,
			totalDesired: totalDesired,
			projectedPanLimit: projectedPanLimit,
			segmentNetExposure: segmentNetExposure,
			panAggregateNetExposure: panAggregateNetExposure,
			triggerToolWorking: triggerToolWorking,
			isToolWorkingDeviation: triggerToolWorking && (panAggregateNetExposure > batchMetrics.finalSafe),
			isCrossSegmentDeviation: panAggregateNetExposure > thresholds.crossSegment
		};
	}

	// Audit narrative
	function buildDetailedAuditNarrative(ctx) {
		var L = [];
		var money = function(n) { return 'Rs.' + (parseFloat(n) || 0).toFixed(2); };

		L.push('===== SYSTEM-CALCULATED RISK & LIMIT DETERMINATION =====');
		L.push('Generated: ' + new GlideDateTime().getDisplayValue());
		L.push('PAN: ' + ctx.pan + ' | Company Type: ' + ctx.companyType);

		if (ctx.isListed) {
			L.push('');
			L.push('-- Listed Entity PAN-Level MACL Calculation --');
			L.push('Net Worth: ' + money(ctx.netWorth) + ' | Loans & Advances: ' + money(ctx.loansAdvances));
			L.push('Formula: PAN MACL = 0.05 x (Net Worth - 0.5 x Loans & Advances)');
			L.push('       = 0.05 x (' + money(ctx.netWorth) + ' - 0.5 x ' + money(ctx.loansAdvances) + ')');
			L.push('       = ' + money(ctx.panP1IfListed) + ' (floored at 0 if the result was negative)');
		}

		L.push('');
		L.push('-- Internal Rating / Credit Index Derivation --');
		L.push('Source: ALL customer site codes under this PAN, 6-month outstanding aging buckets totalled across every site.');
		L.push('Safe Bucket % (0-60 days): ' + ctx.ratingInfo.pctL.toFixed(2) + '% | Critical+Toxic % (76+ days): ' + ctx.ratingInfo.pctCT.toFixed(2) + '%');
		L.push('Internal Rating Assigned: ' + ctx.batchMetrics.intR + '  [Rule: A = Safe% >= 80 & Crit+Toxic% <= 10 | B = Safe% >= 60 & Crit+Toxic% <= 20 | else C]');

		L.push('');
		L.push('-- Composite Index (P2) — PAN-Level, Segment-Consolidated --');
		L.push('Methodology: For every segment under this PAN, all customer site codes in that segment are gathered (request sites: entered values, other sites: customer master values).');

		ctx.compositeResult.segments.forEach(function(seg) {
			L.push('');
			L.push('  [Segment: ' + seg.segment + '] Site Count: ' + seg.siteCount);
			L.push('    Sum of Potential (all sites): ' + money(seg.potentialSum));
			L.push('    Sum of Expected Potential (scored for Potential parameter): ' + money(seg.expectedPotentialSum));
			L.push('    SOB-weighted Current Share %: ' + seg.currentSobPct.toFixed(2) + '%');
			L.push('    Segment Composite Index: ' + (seg.index * 100).toFixed(2) + '%');
			L.push('    Average Order Rate: ' + money(seg.avgRate) + ' | Financial Weight (MPQ x Avg Rate): ' + money(seg.weight));
			L.push('    Parameters scored:');
			seg.paramTrace.forEach(function(t) {
				L.push('      - ' + t.name + ': ' + t.label + ' | Score ' + t.score + ' | Weight ' + t.weight + ' | ' + t.source);
			});
		});

		L.push('');
		L.push('PAN-Level Composite Index (P2) = Sum(Segment Index x Financial Weight) / Sum(Financial Weight) = ' + (ctx.batchMetrics.batchP2Avg * 100).toFixed(2) + '%' +
					 (ctx.compositeResult.usedFallback ? '  (no segment had a weight, simple average used)' : ''));

		L.push('');
		L.push('-- Site-Level Breakdown (' + ctx.sites.length + ' site(s) in this request) --');

		ctx.sites.forEach(function(row, idx) {
			var m = ctx.batchMetrics.perSite[idx];
			L.push('');
			L.push('[' + row.code + '] Segment: ' + row.segment);
			L.push('  Total Potential: ' + round2(row.totalPotential) +
						 ' | Current SOB: ' + round2(row.currentSob) + ' (' + row.currentSobPct + '%)' +
						 ' | Expected SOB: ' + round2(row.expectedSob) + ' (' + row.expectedSobPct + '%)');
			L.push('  Order Rate: ' + money(row.orderRate) + ' | Credit Tenor: ' + row.creditTenor + ' days | Derived NOD: ' + row.nod + ' days');

			if (ctx.isListed) {
				L.push('  MACL (P1) = PAN-Level MACL applied (Listed Entity) = ' + money(m.p1));
			} else {
				L.push('  MACL (P1) = Expected SOB x Order Rate x (Credit Tenor / 30) = ' + money(m.p1));
			}

			L.push('  Composite Index (P2) = ' + (m.p2 * 100).toFixed(2) + '%');
			L.push('  External Rating: ' + m.extR + ' | Credit Index (P3): ' + m.p3.toFixed(2));
			L.push('  Safe Allowable Limit: ' + money(m.safe));
			L.push('  Desired Limit: ' + money(row.desiredLimit) + (row.desiredLimit > m.safe ? '  >> EXCEEDS Safe Limit' : '  (within Safe Limit)'));
			L.push('  Existing Limit: ' + money(row.limit) + ' | Existing Active BG: ' + money(row.activeBg) + ' | Existing Table Outstanding: ' + money(row.outstanding));
		});

		L.push('');
		L.push('-- Aggregated MACL: all sites under the PAN (request values for selected sites, customer master values for the rest) --');
		(ctx.panSiteRows || []).forEach(function(r) {
			L.push('  [' + r.code + '] ' + (r.segment || '') + (r.inRequest ? ' (in request)' : ' (master)') +
						 ' | Exp. SOB: ' + round2(r.expectedSob) + ' | Rate: ' + money(r.orderRate) + ' | Tenor: ' + r.creditTenor + ' days' +
						 ' | MACL: ' + money(r.macl) + ' | Current CL: ' + money(r.currentCl) + ' | Updated CL: ' + money(r.updatedCl));
		});

		L.push('');
		L.push('-- PAN-Level Aggregate Summary --');
		L.push('Aggregated MACL (P1): ' + money(ctx.batchMetrics.aggregatedP1));
		L.push('PAN-Level Composite Index (P2): ' + (ctx.batchMetrics.batchP2Avg * 100).toFixed(2) + '%');
		L.push('Avg Credit Index (P3): ' + ctx.batchMetrics.avgP3.toFixed(2));
		L.push('Final Safe Allowable Limit = Aggregated MACL x Composite Index x Credit Index = ' + money(ctx.batchMetrics.finalSafe));
		L.push('Total Requested/Desired Limit: ' + money(ctx.totalDesired));
		L.push('Existing PAN Limit: ' + money(ctx.existingPanLimit) + ' | Projected New PAN Limit: ' + money(ctx.projectedPanLimit));

		L.push('');
		L.push('-- Threshold & Deviation Analysis --');
		L.push('Segment: ' + ctx.segment + ' | Tool-Working Threshold: ' + money(ctx.toolWorkingThreshold));
		L.push('Segment Net Exposure: ' + money(ctx.segmentNetExposure));
		L.push('Tool-Working Triggered: ' + (ctx.triggerToolWorking ? 'YES' : 'NO'));
		L.push('PAN Aggregate Net Exposure: ' + money(ctx.panAggregateNetExposure));
		L.push('Deviation Request Required: ' + (ctx.isToolWorkingDeviation ? 'YES' : 'NO'));
		L.push('Cross-Segment PAN Override Flag: ' + (ctx.isCrossSegmentDeviation ? 'YES' : 'NO'));
		L.push('===== END OF SYSTEM CALCULATION =====');

		return L.join('\n');
	}

	// Submit
	function handleSubmitCreditRequest() {
		var siteCount = input.selectedCustomers.length;
		var isListed = (input.panLevel.companyType === 'Listed');

		var totalPanLimit = 0;
		var totalCurrentLimitSelected = 0;
		var totalPotentialSum = 0;
		var totalExpectedSobSum = 0;
		var totalCurrSobSum = 0;
		var totalCurrSobPct = 0;
		var totalExpSobPct = 0;

		var panP1 = 0;
		if (isListed) {
			var nw = parseFloat(input.panLevel.netWorth) || 0;
			var la = parseFloat(input.panLevel.loansAdvances) || 0;
			panP1 = Math.max(0, 0.05 * (nw - 0.5 * la));
		}

		for (var vs = 0; vs < siteCount; vs++) {
			var subSobErr = validateSob(input.selectedCustomers[vs]);
			if (subSobErr) { data.serverError = subSobErr; return; }
		}

		var totalUnlistedP1 = 0;
		for (var p = 0; p < siteCount; p++) {
			var st = input.selectedCustomers[p];
			if (st.creditTenor === null || st.creditTenor === undefined || st.creditTenor === '') {
				st.creditTenor = CONFIG.DEFAULT_CREDIT_TENOR;
			}

			var stSob = getSobFigures(st);
			var pot = stSob.pot;
			var cPct = stSob.curPct;
			var ePct = stSob.expPct;
			var currSobAmt = stSob.curQty;
			var expSobAmt = stSob.expQty;

			totalPanLimit             += parseFloat(st.desiredLimit) || 0;
			totalCurrentLimitSelected += parseFloat(st.limit)        || 0;
			totalPotentialSum   += pot;
			totalCurrSobSum     += currSobAmt;
			totalExpectedSobSum += expSobAmt;
			totalCurrSobPct      += cPct;
			totalExpSobPct       += ePct;

			var siteP1;
			if (isListed) {
				siteP1 = panP1;
			} else {
				siteP1 = expSobAmt * (parseFloat(st.orderRate) || 0) * ((parseInt(st.creditTenor, 10) || 0) / 30);
			}
			if (isNaN(siteP1) || siteP1 < 0) siteP1 = 0;
			st.calculatedP1 = siteP1;
			totalUnlistedP1 += siteP1;
		}
		if (!isListed) panP1 = totalUnlistedP1;

		var activeSegment = siteCount > 0 ? (input.selectedCustomers[0].segmentDisplay || '') : '';
		var segmentLimitTotal = 0, segmentBgTotal = 0;
		(input.customers || []).forEach(function(cst) {
			if (cst.segmentDisplay === activeSegment) {
				var picked = input.selectedCustomers.find(function(sc) { return sc.code === cst.code; });
				segmentLimitTotal += picked ? parseFloat(picked.desiredLimit || 0) : parseFloat(cst.limit || 0);
				segmentBgTotal += parseFloat(cst.activeBg || 0);
			}
		});
		var segmentNetExposure = segmentLimitTotal - segmentBgTotal;
		var panAggregateNetExposure = (parseFloat(input.panTotals.limit) || 0) - (parseFloat(input.panTotals.activeBg) || 0) + segmentNetExposure;

		var grBatch = new GlideRecord(CONFIG.TABLES.PAN_REQUEST);
		grBatch.initialize();
		grBatch.setValue('pan', input.panNumber);
		if (siteCount > 0) grBatch.setValue('segment', input.selectedCustomers[0].segmentValue || input.selectedCustomers[0].segmentDisplay);

		var effectivePanTotal = parseFloat(input.panTotals.limit) || 0;
		var projectedPanTotal = effectivePanTotal - totalCurrentLimitSelected + totalPanLimit;

		grBatch.setValue('total_existing_limit',   projectedPanTotal);
		grBatch.setValue('total_requested_limit',  totalPanLimit);
		grBatch.setValue('total_existing_bg',      input.panTotals.activeBg);
		grBatch.setValue('total_potential',        totalPotentialSum);
		grBatch.setValue('total_ut_sob',           totalCurrSobSum);
		grBatch.setValue('total_expected_sob',     totalExpectedSobSum);
		grBatch.setValue('total_ut_sob_per',       siteCount > 0 ? (totalCurrSobPct / siteCount) : 0);
		grBatch.setValue('total_expected_sob_per', siteCount > 0 ? (totalExpSobPct / siteCount) : 0);
		grBatch.setValue('total_net_exposure',     panAggregateNetExposure);
		grBatch.setValue('segment_net_exposure',   segmentNetExposure);
		grBatch.setValue('state', -5);

		var panJustificationText = (input.panLevel && input.panLevel.panNote) ? input.panLevel.panNote.trim() : '';
		var consolidatedSiteComments = [];

		for (var k = 0; k < siteCount; k++) {
			var siteRow = input.selectedCustomers[k];
			if (siteRow.justification && siteRow.justification.trim() !== '') {
				consolidatedSiteComments.push('• Site [' + siteRow.code + ']: ' + siteRow.justification.trim());
			}
		}

		var fullDescription = '';
		if (panJustificationText) {
			fullDescription += 'PAN-Level Strategic Rationale & Justification:\n' + panJustificationText;
		}
		if (consolidatedSiteComments.length > 0) {
			if (fullDescription) fullDescription += '\n\n';
			fullDescription += 'Site-Level Commercial Justifications:\n' + consolidatedSiteComments.join('\n');
		}

		grBatch.setValue('description', fullDescription);
		grBatch.setValue('company_type', input.panLevel.companyType.toString().toLowerCase());
		grBatch.setValue('total_macl',   parseFloat(panP1));

		var newBatchSysId = grBatch.insert();

		if (!newBatchSysId) {
			data.serverError = 'Failed to create PAN request record.';
			return;
		}

		snapshotPanLevelAgingBuckets(newBatchSysId, input.panNumber);

		if (input.fileData && input.fileName && input.fileType) {
			safeAttach(grBatch, input.fileName, input.fileType, input.fileData);
		}

		if (input.auditLogsPayload) {
			var auditGr = new GlideRecord(CONFIG.TABLES.PAN_REQUEST);
			if (auditGr.get(newBatchSysId)) {
				auditGr.work_notes = 'Risk Parameter Overrides & Lowest-Score Defaults Logged by Initiator:\n' + input.auditLogsPayload;
				auditGr.update();
			}
		}

		if (input.sysId && input.targetTable) {
			var ocrUpdateGr = new GlideRecord(input.targetTable);
			if (ocrUpdateGr.get(input.sysId) && ocrUpdateGr.isValidField('request')) {
				ocrUpdateGr.setValue('request', newBatchSysId);
				ocrUpdateGr.update();
			}
		}

		// PAN-level site rows (request sites: entered values, other sites: customer master) and the composite
		// result are computed BEFORE the parameters are stored, so the segment parameters (Current SOB %, Potential)
		// are saved from the correct PAN-level totals of the segment, not from the selected sites only.
		var panSiteRows = buildPanSiteRows(isListed);
		var compositeResult = computePanLevelCompositeIndex(input.panNumber, input.groupedParameters, panSiteRows);
		var activeSegKey = segKey(activeSegment) || activeSegment;

		// Option chosen from the PAN-level totals of the requested segment, by parameter name
		var aggOptByName = {};
		compositeResult.segments.forEach(function(sr) {
			if (sr.segment !== activeSegKey) return;
			sr.paramTrace.forEach(function(t) { if (t.kind) aggOptByName[t.name] = t.optionId; });
		});

		var clientSelByName = {};
		(input.selectedMatrixParams || []).forEach(function(pm) { clientSelByName[pm.name] = pm.sys_id; });

		var paramsToStore = [];
		for (var pCat in (input.groupedParameters || {})) {
			(input.groupedParameters[pCat] || []).forEach(function(gp) {
				if (!isParamRelevant(gp, activeSegment)) return;
				var optId = aggOptByName[gp.name] || clientSelByName[gp.name];
				if (!optId) {
					var low = getLowestOption(gp);
					if (low) optId = low.sys_id;
				}
				if (optId) paramsToStore.push({ sys_id: optId, name: gp.name, segmentTag: gp.segmentTag || '' });
			});
		}

		paramsToStore.forEach(function(pMap) {
			var grParam = new GlideRecord(CONFIG.TABLES.REQ_PARAMS);
			grParam.initialize();
			grParam.setValue('request', newBatchSysId);
			grParam.setValue('risk_parameter', pMap.sys_id);
			if (grParam.isValidField('segment')) grParam.setValue('segment', activeSegKey);
			grParam.insert();
		});

		var insertedRequestIds = [];

		for (var i = 0; i < siteCount; i++) {
			var row = input.selectedCustomers[i];
			var desiredLimit = parseFloat(row.desiredLimit) || 0;
			var rowSob = getSobFigures(row);
			var rowPot = rowSob.pot;
			var rowCurrSobAmt = rowSob.curQty;
			var rowExpSobAmt = rowSob.expQty;

			var nextReviewGdt = new GlideDateTime();
			nextReviewGdt.addYearsUTC(1);

			var grReq = new GlideRecord(CONFIG.TABLES.SITE_REQUEST);
			grReq.initialize();
			grReq.setValue('pan_request',             newBatchSysId);
			grReq.setValue('customer_site_code',      row.sys_id);
			grReq.setValue('segment',                 row.segmentValue || row.segmentDisplay);
			grReq.setValue('order_rate',              parseFloat(row.orderRate) || 0);
			grReq.setValue('nod',                     row.nod || 0);
			grReq.setValue('credit_tenor',            parseFloat(row.creditTenor) || CONFIG.DEFAULT_CREDIT_TENOR);
			grReq.setValue('macl',                    parseFloat(row.calculatedP1));
			grReq.setValue('requested_limit',         desiredLimit);
			grReq.setValue('total_potential',         rowPot);
			grReq.setValue('ut_sob',                  rowCurrSobAmt);
			grReq.setValue('expected_sob',            rowExpSobAmt);
			grReq.setValue('ut_sob_per',              rowSob.curPct);
			grReq.setValue('expected_sob_per',        rowSob.expPct);
			grReq.setValue('existing_credit_limit',   row.limit);
			grReq.setValue('existing_bg',             row.activeBg);
			grReq.setValue('existing_outstanding',    row.outstanding);

			var siteJustificationText = row.justification || '';
			grReq.setValue('description', siteJustificationText);

			grReq.setValue('proposed_next_review',    nextReviewGdt.getDate());
			grReq.setValue('sap_sync_status',         'pending');
			grReq.setValue('sap_sync_message',        'Awaiting automatic sync dispatch');

			var newRequestId = grReq.insert();

			insertedRequestIds.push({
				requestId: newRequestId, custSysId: row.sys_id, code: row.code, segment: row.segmentDisplay,
				totalPotential: rowPot,
				currentSob: rowCurrSobAmt,
				expectedSob: rowExpSobAmt,
				currentSobPct: rowSob.curPct,
				expectedSobPct: rowSob.expPct,
				orderRate: parseFloat(row.orderRate) || 0,
				creditTenor: row.creditTenor, nod: row.nod || 0,
				expectedPotentialAmt: rowExpSobAmt,
				limit: row.limit, activeBg: row.activeBg, outstanding: row.outstanding,
				desiredLimit: desiredLimit,
				p1: row.calculatedP1
			});
		}

		persistFinalScoresAndNarrative(
			newBatchSysId, input.externalRating || '', insertedRequestIds, input.panNumber, input.panLevel,
			isListed, panP1, totalPanLimit, projectedPanTotal, effectivePanTotal,
			segmentNetExposure, panAggregateNetExposure, input.groupedParameters,
			panSiteRows, activeSegKey, compositeResult
		);

		data.success = true;
	}

	function persistFinalScoresAndNarrative(batchSysId, externalRatingInput, siteRows, panQueryVal, panLevelInput, isListed, panP1IfListed, totalDesired, projectedPanLimit, existingPanLimit, segmentNetExposure, panAggregateNetExposure, groupedParameters, panSiteRows, activeSegKey, precomputedComposite) {
		var compositeResult = precomputedComposite || computePanLevelCompositeIndex(panQueryVal, groupedParameters, panSiteRows);
		var panMaclAll = sumBy(panSiteRows || [], 'macl');
		var batchP2 = compositeResult.panIndex;

		// Other segments of the PAN: their segment parameters (PAN-level Current SOB % / Potential) are stored too
		storeOtherSegmentParameters(batchSysId, compositeResult.segments, activeSegKey);

		var sites = siteRows.map(function(s) {
			return { p1: s.p1 };
		});

		var ratingInfo = getInternalRating(panQueryVal);
		var batchMetrics = computeBatchMetrics(sites, ratingInfo.rating, isListed, panP1IfListed, externalRatingInput, batchP2, panMaclAll);

		for (var s = 0; s < siteRows.length; s++) {
			var updateGr = new GlideRecord(CONFIG.TABLES.SITE_REQUEST);
			if (updateGr.get(siteRows[s].requestId)) {
				updateGr.setValue('composite_index',      parseFloat(batchMetrics.perSite[s].p2).toFixed(4));
				updateGr.setValue('credit_index',          parseFloat(batchMetrics.perSite[s].p3));
				updateGr.setValue('safe_allowable_limit', parseFloat(batchMetrics.perSite[s].safe));
				updateGr.update();
			}
		}

		var bGr = new GlideRecord(CONFIG.TABLES.PAN_REQUEST);
		if (!bGr.get(batchSysId)) return;

		if (!isListed) bGr.setValue('total_macl', parseFloat(batchMetrics.aggregatedP1));
		bGr.setValue('total_composite_index',      parseFloat(batchMetrics.batchP2Avg).toFixed(4));
		bGr.setValue('total_credit_index',          parseFloat(batchMetrics.avgP3));
		bGr.setValue('total_safe_allowable_limit', parseFloat(batchMetrics.finalSafe));

		var segment = bGr.getValue('segment');
		var thresholds = getThresholds();
		var toolWorkingThreshold = getToolWorkingThreshold(segment, thresholds);

		var triggerToolWorking = (segmentNetExposure >= toolWorkingThreshold);
		var isDev = triggerToolWorking && (panAggregateNetExposure > batchMetrics.finalSafe);
		var panCross = panAggregateNetExposure > thresholds.crossSegment;

		bGr.setValue('is_deviation', isDev ? 1 : 0);
		bGr.setValue('pan_override', panCross ? 1 : 0);

		var auditNarrative = buildDetailedAuditNarrative({
			pan: panQueryVal,
			companyType: panLevelInput.companyType,
			isListed: isListed,
			netWorth: parseFloat(panLevelInput.netWorth) || 0,
			loansAdvances: parseFloat(panLevelInput.loansAdvances) || 0,
			panP1IfListed: panP1IfListed,
			ratingInfo: ratingInfo,
			batchMetrics: batchMetrics,
			compositeResult: compositeResult,
			sites: siteRows,
			panSiteRows: panSiteRows || [],
			totalDesired: totalDesired,
			existingPanLimit: existingPanLimit,
			projectedPanLimit: projectedPanLimit,
			segment: segment,
			toolWorkingThreshold: toolWorkingThreshold,
			thresholds: thresholds,
			segmentNetExposure: segmentNetExposure,
			panAggregateNetExposure: panAggregateNetExposure,
			triggerToolWorking: triggerToolWorking,
			isToolWorkingDeviation: isDev,
			isCrossSegmentDeviation: panCross
		});

		bGr.comments = auditNarrative;
		bGr.update();

		new x_birl3_clm.CLM_ApprovalUtil().populateApprovers(batchSysId);
	}

	// Dispatch
	var handlers = {
		fetch_pan_suggestions: handleFetchPanSuggestions,
		fetch_customers:       handleFetchCustomers,
		fetch_sap_data:        handleFetchSapData,
		fetch_parameters:      handleFetchParameters,
		create_record:         handleCreateRecord,
		poll:                  handlePoll,
		preview_review:        handlePreviewReview,
		submit_credit_request: handleSubmitCreditRequest
	};

	if (handlers[input.action]) {
		handlers[input.action]();
	}

})();
